"Gesucht: x₁, x₂ mit x₁ + x₂ = {0} und x₁ · x₂ = {1}": "Find: x₁, x₂ with x₁ + x₂ = {0} and x₁ · x₂ = {1}",
"Gibt an, wie oft der Linearfaktor (x − x₀) im Produkt vorkommt. Einfache NS (n={0}): Graph kreuzt die x-Achse. Doppelte NS (n={1}): Graph berührt die x-Achse (Wendepunkt bei der NS möglich).": "Indicates how often the linear factor (x − x₀) occurs in the product. Simple zero (n={0}): the graph crosses the x-axis. Double zero (n={1}): the graph touches the x-axis (inflection point at the zero possible).",
"Gibt den absoluten (nicht-negativen) Wert von x zurück: |x| = x für x ≥ {0}, |x| = −x für x {1} {2}. Graph: V-förmig mit Knick bei x = {3}. Nicht differenzierbar bei x = {4}.": "Returns the absolute (non-negative) value of x: |x| = x for x ≥ {0}, |x| = −x for x {1} {2}. Graph: V-shaped with a corner at x = {3}. Not differentiable at x = {4}.",
