"Unerwartetes Zeichen «=»": "Unexpected character «=»",
"Binomische Formeln, Ausmultiplizieren, Faktorisieren, quadratische Ergänzung, Potenzen, Wurzeln, Logarithmen, Bruchterme, Gleichungen und Gleichungssysteme als Bild": "Binomial formulas, expanding, factorising, completing the square, powers, roots, logarithms, rational expressions, equations and systems of equations as pictures",
"Wurzel und rationale Hochzahl": "Root and rational exponent",
"Gleichung und Äquivalenzumformung": "Equation and equivalence transformation",
"Quadratische Gleichung (Lösungsformel, Diskriminante)": "Quadratic equation (formula, discriminant)",
"Bruchgleichung und Scheinlösung": "Fractional equation and extraneous solution",
"── Wurzeln ──": "── Roots ──",
