"Wird der Zins mehrmals pro Jahr gutgeschrieben, rechnet man mit dem konformen Zinssatz, der über das Jahr genau den Jahreszins ergibt.": "If interest is credited several times a year, use the equivalent interest rate, which gives exactly the annual rate over the year.",
