"Der Punkt P liegt fest auf dem Graphen, der Punkt Q wandert. Die Sekante durch P und Q hat die Steigung ms = Δy / h.": "The point P is fixed on the graph, the point Q moves. The secant through P and Q has the slope ms = Δy / h.",
"Ziehe Q (oder benutze den Regler) gegen P: Die Sekante wird zur Tangente, und ms nähert sich der Ableitung f′(x₀). Ziehe P, um die Stelle zu ändern.": "Drag Q (or use the slider) towards P: the secant becomes the tangent, and ms approaches the derivative f′(x₀). Drag P to change the point.",
