"Oben der Graph von f, unten der Graph der Ableitung f′. Ziehe den Punkt: Die Höhe des unteren Punktes ist die Steigung der Tangente oben.": "Top: the graph of f, bottom: the graph of the derivative f′. Drag the point: the height of the lower point is the slope of the tangent above.",
