"Differenzenquotient und Grenzwert": "Difference quotient and limit",
"Bei dieser Funktion lässt sich der Differenzenquotient nicht zu einem Term vereinfachen, der sich durch {0} kürzen lässt. Die Tabelle zeigt, wohin die Differenzenquotienten streben. Die Ableitung berechnest du mit den Ableitungsregeln.": "For this function the difference quotient cannot be simplified to a term that can be cancelled by {0}. The table shows where the difference quotients are heading. You calculate the derivative with the differentiation rules.",
"Bei dieser Funktion lässt sich der Differenzenquotient nicht zu einem Term vereinfachen, der sich durch {0} kürzen lässt. Die Ableitungsfunktion findest du mit den Ableitungsregeln.": "For this function the difference quotient cannot be simplified to a term that can be cancelled by {0}. You find the derivative function with the differentiation rules.",
