"<0>Integralrechnung</0><1>Ober- und Untersummen, Integralfunktion und Hauptsatz, Stammfunktion mit Regeln, Flächen zwischen Kurven, Rotationskörper</1>": "<0>Integral calculus</0><1>Upper and lower sums, integral function and fundamental theorem, antiderivative with rules, areas between curves, solids of revolution</1>",
"<0>Algebra</0><1>Binomische Formeln, Ausmultiplizieren, Faktorisieren, quadratische Ergänzung, Potenzen, Wurzeln, Logarithmen, Bruchterme, Gleichungen und Gleichungssysteme als Bild</1>": "<0>Algebra</0><1>Binomial formulas, expanding, factorising, completing the square, powers, roots, logarithms, algebraic fractions, equations and systems of equations as pictures</1>",
"<0>Wahrscheinlichkeit & Statistik</0><1>Zufallsexperimente zum Mitverfolgen: Würfel, Galtonbrett, π, Ziegenproblem, Grenzwertsatz, Konfidenzintervalle</1>": "<0>Probability & statistics</0><1>Random experiments to follow live: dice, Galton board, π, Monty Hall problem, central limit theorem, confidence intervals</1>",
"<0>Finanzmathematik</0><1>Zeitstrahl und Konten, Summenzeichen, Sparplan, Kredit mit Tilgungsplan, Zeitwert, Marchzins, konformer Zins</1>": "<0>Financial mathematics</0><1>Timeline and accounts, summation sign, savings plan, loan with repayment schedule, present value, broken-period interest, equivalent interest rate</1>",
"Das Intervall wird in {0} gleich breite Streifen der Breite {1} geteilt. Die <2>Untersumme</2> nimmt in jedem Streifen den kleinsten, die <3>Obersumme</3> den grössten Funktionswert als Höhe des Rechtecks.": "The interval is divided into {0} strips of equal width {1}. The <2>lower sum</2> uses the smallest function value in each strip as the height of the rectangle, the <3>upper sum</3> the largest.",
"Für {0} streben beide Summen gegen {1}.": "For {0}, both sums tend to {1}.",
"<0>Schritt {1}:</0> {2} einsetzen, ausmultiplizieren.": "<0>Step {1}:</0> Substitute {2} and expand.",
"Oben der Graph von f mit der gefärbten Fläche von a bis x, unten die Integralfunktion Fa(x) = ∫ f. Ziehe den Punkt x: Der untere Punkt zeigt, wie viel Fläche bis dahin gesammelt wurde.": "Top: the graph of f with the coloured area from a to x; bottom: the integral function Fa(x) = ∫ f. Drag the point x: the lower point shows how much area has been collected so far.",
"Die Steigung von Fa an der Stelle x ist {0}: Wo f positiv ist, steigt Fa (grün), wo f negativ ist, fällt Fa (orange). Das ist der Hauptsatz.": "The slope of Fa at x is {0}: where f is positive, Fa increases (green); where f is negative, Fa decreases (orange). This is the fundamental theorem.",
"Untere Grenze und Stelle": "Lower limit and position",
"Stelle x": "Position x",
"{0} x wandert nach rechts": "{0} x moves to the right",
"{0} <1>Fläche von a bis x färben</1>": "{0} <1>Colour area from a to x</1>",
"{0} <1>Tangente an Fa zeigen (Steigung {2})</1>": "{0} <1>Show tangent to Fa (slope {2})</1>",
"Rechenweg: Integralfunktion": "Working: integral function",
"Die <0>Integralfunktion</0> sammelt die Fläche zwischen {1} und der {2}-Achse ab der festen Stelle {3}. Oberhalb der Achse wächst sie, unterhalb nimmt sie ab.": "The <0>integral function</0> collects the area between {1} and the {2}-axis from the fixed point {3}. Above the axis it grows, below it decreases.",
"<0>Schritt {1}:</0> Eine Stammfunktion {2} von {3} bestimmen.": "<0>Step {1}:</0> Find an antiderivative {2} of {3}.",
"<0>Schritt {1}:</0> Hauptsatz der Differential- und Integralrechnung.": "<0>Step {1}:</0> Fundamental theorem of calculus.",
"<0>Schritt {1}:</0> Ableiten der Integralfunktion gibt die Funktion zurück:": "<0>Step {1}:</0> Differentiating the integral function returns the function:",
"Die Steigung von {0} an der Stelle {1} ist {2}.": "The slope of {0} at {1} is {2}.",
"Für diese Funktion gibt es keine Stammfunktion in einfacher Form; die Integralfunktion wird numerisch berechnet.": "This function has no antiderivative in simple form; the integral function is computed numerically.",
"Die Stammfunktion wird Schritt für Schritt mit den Integrationsregeln bestimmt. Danach folgt das bestimmte Integral zwischen a und b.": "The antiderivative is found step by step with the integration rules. Then comes the definite integral between a and b.",
"Ziehe a und b auf der x-Achse. Die Stammfunktion ist nur bis auf eine Konstante C bestimmt: Alle Stammfunktionen sind gegeneinander verschoben.": "Drag a and b on the x-axis. The antiderivative is only determined up to a constant C: all antiderivatives are shifted copies of each other.",
"{0} <1>Fläche von a bis b färben</1>": "{0} <1>Colour area from a to b</1>",
"{0} <1>Stammfunktion F einzeichnen</1>": "{0} <1>Draw antiderivative F</1>",
