"<0>Schritt {1}:</0> Schnittstellen von {2} und {3} im Intervall suchen ({4}).": "<0>Step {1}:</0> Find the intersections of {2} and {3} in the interval ({4}).",
"Dreht man den Graphen von f um die x-Achse, entsteht ein Körper aus lauter dünnen Kreisscheiben. Jede Scheibe hat das Volumen π · {0}² · Δx.": "If the graph of f is rotated about the x-axis, a solid made of many thin discs is formed. Each disc has volume π · {0}² · Δx.",
"Erhöhe die Zahl der Scheiben: Die Summe der Scheibenvolumen nähert sich dem Volumen V = π ∫ f².": "Increase the number of discs: the sum of the disc volumes approaches the volume V = π ∫ f².",
