"Die Steigung ist positiv: Die Gerade steigt.": "The slope is positive: the line rises.",
"Die Steigung ist negativ: Die Gerade fällt.": "The slope is negative: the line falls.",
"Die Gerade verläuft parallel zur {0}-Achse und hat keine Nullstelle.": "The line is parallel to the {0}-axis and has no zero.",
"Die Steigung ist null: Die Gerade verläuft waagrecht.": "The slope is zero: the line is horizontal.",
"Die Gerade ist die {0}-Achse selbst: Jede Stelle ist eine Nullstelle.": "The line is the {0}-axis itself: every point is a zero.",
"Jede Stelle ist Nullstelle": "Every point is a zero",
"Das ist keine lineare Funktion. Erlaubt ist m·x + q.": "This is not a linear function. Allowed is m·x + q.",
"Eine Gerade ist durch zwei Punkte oder durch einen Punkt und die Steigung festgelegt. Aus Δy und Δx folgt m, dann folgt q aus einem Punkt.": "A line is determined by two points or by one point and the slope. Δy and Δx give m, then q follows from a point.",
"Ziehe die Punkte P und Q. Mit dem Punkt R kannst du die Parallele und die Senkrechte zur Geraden durch R zeigen.": "Drag the points P and Q. With the point R you can show the parallel and the perpendicular to the line through R.",
