"<0>Symmetrie:</0> Setze {1} ein. Das Vorzeichen eines Produkts aus {2} Faktoren {3} hängt davon ab, ob {4} gerade oder ungerade ist.": "<0>Symmetry:</0> Substitute {1}. The sign of a product of {2} factors {3} depends on whether {4} is even or odd.",
"{0} ungerade: {1}, der Graph ist <2>punktsymmetrisch zum Ursprung</2>.": "{0} odd: {1}, the graph is <2>point-symmetric about the origin</2>.",
"<0>Gemeinsame Punkte:</0> Alle Potenzfunktionen gehen durch {1} und {2} und, weil {3} ungerade ist, durch {4}.": "<0>Common points:</0> All power functions pass through {1} and {2} and, because {3} is odd, through {4}.",
"<0>Monotonie und Verlauf:</0> Der Graph steigt auf ganz {1} (streng monoton wachsend).": "<0>Monotonicity and behaviour:</0> The graph increases on all of {1} (strictly increasing).",
"<0>Vergleich mit kleineren Exponenten:</0> Für {1} wird {2} mit wachsendem {3} kleiner, für {4} grösser. Darum liegen die Graphen zwischen {5} und {6} unter der Normalparabel und ausserhalb darüber. Je grösser {7}, desto flacher nahe {8} und desto steiler aussen.": "<0>Comparison with smaller exponents:</0> For {1}, {2} becomes smaller as {3} increases, for {4} it becomes larger. Hence between {5} and {6} the graphs lie below the standard parabola and outside that interval above it. The larger {7}, the flatter near {8} and the steeper further out.",
