"Die Wurzelfunktion ⁿ√x ist die Umkehrfunktion von xⁿ: Ihr Graph ist das Spiegelbild an der Winkelhalbierenden y = x. In Potenzschreibweise ist ⁿ√x = x^({0}/n), allgemein x^(m/n) = ⁿ√(xᵐ).": "The root function ⁿ√x is the inverse function of xⁿ: its graph is the reflection in the line y = x. In power notation ⁿ√x = x^({0}/n), in general x^(m/n) = ⁿ√(xᵐ).",
