"Für {0} gilt: Je grösser der Exponent, desto grösser die Potenz: {1}. Zwischen {2} und {3} ist es umgekehrt.": "For {0} the following holds: the larger the exponent, the larger the power: {1}. Between {2} and {3} it is the other way round.",
"Die allgemeine Form {0} = a·(x−v)ⁿ + h entsteht aus der Grundfunktion xⁿ (oder ⁿ√x, {1}/xⁿ) durch Strecken mit a (bei a {2} {3} gespiegelt), Verschieben um v nach rechts und um h nach oben.": "The general form {0} = a·(x−v)ⁿ + h arises from the base function xⁿ (or ⁿ√x, {1}/xⁿ) by stretching with a (reflected if a {2} {3}), shifting by v to the right and by h upwards.",
