"Exponentialfunktion": "Exponential function",
"Für {0} ist {1} konstant: {2}.": "For {0}, {1} is constant: {2}.",
"Die Zahl e ≈ {0} entsteht als Grenzwert von ({1} + {2}/n)ⁿ. Die Funktion eˣ hat eine besondere Eigenschaft: Die Steigung der Tangente ist an jeder Stelle gleich dem Funktionswert.": "The number e ≈ {0} arises as the limit of ({1} + {2}/n)ⁿ. The function eˣ has a special property: the slope of the tangent at every point equals the function value.",
"Ziehe den Berührpunkt T und vergleiche die Steigung mit dem Funktionswert. Die grauen Kurven {0}ˣ und {1}ˣ zeigen, dass nur bei der Basis e die Steigung im Punkt ({2} | {3}) genau {4} ist.": "Drag the point of contact T and compare the slope with the function value. The grey curves {0}ˣ and {1}ˣ show that only for the base e is the slope at the point ({2} | {3}) exactly {4}.",
