"Rechenweg: Die Zahl e": "Working: the number e",
"Die Zahl e und die Funktion e^x": "The number e and the function e^x",
"<0>Woher kommt e?</0> Ein Kapital wächst um {1} pro Jahr. Wird der Zins in {2} Teilschritten gutgeschrieben, wächst es mit dem Faktor {3}. Je feiner die Schritte, desto näher kommt der Faktor einer festen Zahl:": "<0>Where does e come from?</0> A capital grows by {1} per year. If the interest is credited in {2} sub-steps, it grows by the factor {3}. The finer the steps, the closer the factor gets to a fixed number:",
"<0>Die Besonderheit von</0> {1}: Die Steigung der Tangente ist an jeder Stelle gleich dem Funktionswert. Die Funktion ist ihre eigene Ableitung.": "<0>The special property of</0> {1}: the slope of the tangent at every point equals the function value. The function is its own derivative.",
"<0>Tangente an der Stelle</0> {1}: Steigung {2}, Berührpunkt {3}.": "<0>Tangent at</0> {1}: slope {2}, point of contact {3}.",
"<0>Andere Basen:</0> Bei {1} ist die Steigung im Punkt {2} nur {3}, bei {4} schon {5}. Genau bei der Basis {6} ist sie {7}. Allgemein gilt:": "<0>Other bases:</0> For {1} the slope at the point {2} is only {3}, for {4} already {5}. Exactly at the base {6} it is {7}. In general:",
"Jede Exponentialfunktion lässt sich mit der Basis {0} schreiben: {1}. Darum rechnet man in der Analysis fast nur mit {2} und {3}.": "Every exponential function can be written with the base {0}: {1}. That is why in calculus one works almost only with {2} and {3}.",
"{0} ist die Basis, bei der Funktionswert und Steigung überall übereinstimmen": "{0} is the base for which function value and slope agree everywhere",
"Der Logarithmus zur Basis b ist die Umkehrung von bˣ: log_b(y) ist der Exponent, mit dem man b potenzieren muss, um y zu erhalten. Der Graph von log_b x ist das Spiegelbild von bˣ an der Winkelhalbierenden y = x.": "The logarithm to the base b is the inverse of bˣ: log_b(y) is the exponent to which b must be raised to obtain y. The graph of log_b x is the mirror image of bˣ in the line y = x.",
"Ziehe den Punkt P auf der Exponentialfunktion: Sein Spiegelpunkt P′ liegt auf dem Logarithmus. Wähle die Basis b (auch e oder {0}) und vergleiche die Wertetabellen.": "Drag the point P on the exponential function: its mirror point P′ lies on the logarithm. Choose the base b (also e or {0}) and compare the tables of values.",
