"Rechenweg: Logarithmus": "Working: logarithm",
"<0>Die Frage umdrehen:</0> Bei {1} fragt man: Welcher Wert gehört zu {2}? Die Umkehrung fragt: <3>Mit welchem Exponenten</3> muss ich {4} potenzieren, um {5} zu erhalten? Dieser Exponent heisst <6>Logarithmus</6> von {7} zur Basis {8}.": "<0>Turning the question around:</0> For {1} one asks: which value belongs to {2}? The inverse asks: <3>to which exponent</3> must I raise {4} to obtain {5}? This exponent is called the <6>logarithm</6> of {7} to the base {8}.",
"<0>Spiegelung:</0> Der Graph von {1} ist das Spiegelbild des Graphen von {2} an der Winkelhalbierenden {3}: Aus {4} wird {5}.": "<0>Reflection:</0> The graph of {1} is the mirror image of the graph of {2} in the line {3}: {4} becomes {5}.",
"<0>Definitions- und Wertebereich tauschen:</0> {1} nimmt nur positive Werte an ({2}), also ist {3} nur für positive Zahlen definiert. Die {4}-Achse ist senkrechte Asymptote von {5}.": "<0>Swapping domain and range:</0> {1} takes only positive values ({2}), so {3} is defined only for positive numbers. The {4}-axis is a vertical asymptote of {5}.",
"<0>Besondere Werte:</0> {1} und {2}, also:": "<0>Special values:</0> {1} and {2}, so:",
"<0>Logarithmengesetze</0> (aus den Potenzgesetzen): Ein Produkt wird zur Summe, ein Quotient zur Differenz, eine Potenz zum Vielfachen.": "<0>Laws of logarithms</0> (from the laws of exponents): a product becomes a sum, a quotient a difference, a power a multiple.",
"<0>Basiswechsel:</0> Der Taschenrechner kennt {1} (Basis {2}) und {3} (Basis {4}). Jeden Logarithmus erhält man als Quotient:": "<0>Change of base:</0> The calculator knows {1} (base {2}) and {3} (base {4}). Every logarithm is obtained as a quotient:",
"<0>Beispiel:</0> {1}.": "<0>Example:</0> {1}.",
"{0} ist die Umkehrfunktion von {1}: {2} und {3}": "{0} is the inverse function of {1}: {2} and {3}",
"<0>Natürlicher Logarithmus:</0> {1} ist der Logarithmus zur Basis {2}; er ist die Umkehrung von {3}: {4} und {5} für {6}.": "<0>Natural logarithm:</0> {1} is the logarithm to the base {2}; it is the inverse of {3}: {4} and {5} for {6}.",
"Exponentialgleichungen a·bˣ + d = c werden mit dem Logarithmus gelöst: Potenz isolieren, dann x = log_b(…) = ln(…)/ln(b). Anwendungen: Zinseszins, Bevölkerung, Zerfall, Abkühlung – überall, wo sich etwas pro Zeitschritt um denselben Faktor ändert.": "Exponential equations a·bˣ + d = c are solved using the logarithm: isolate the power, then x = log_b(…) = ln(…)/ln(b). Applications: compound interest, population, decay, cooling – wherever something changes by the same factor per time step.",
"Ziehe die orange Gerade y = c auf und ab: Die Lösung ist die Schnittstelle mit dem Graphen. Wähle eine Anwendung – die Achsen tragen dann Einheiten und das Ergebnis wird gedeutet.": "Drag the orange line y = c up and down: the solution is the point where it meets the graph. Choose an application – the axes then carry units and the result is interpreted.",
