"Der Tangens ist das Verhältnis sin φ / cos φ – die Steigung des Strahls durch P. Am Einheitskreis liest man ihn an der senkrechten Tangente bei x = {0} ab. Wo der Kosinus {1} ist ({2}°, {3}°, …), hat der Tangens Polstellen; seine Periode ist nur π.": "The tangent is the ratio sin φ / cos φ – the slope of the ray through P. On the unit circle it is read off on the vertical tangent line at x = {0}. Where the cosine is {1} ({2}°, {3}°, …), the tangent has poles; its period is only π.",
"Ziehe den Punkt P und beobachte den grünen Tangentenabschnitt. Nahe {0}° wird er riesig. Rechts der Graph mit den Polstellen und die wichtigsten Beziehungen zwischen sin, cos und tan.": "Drag the point P and watch the green tangent segment. Near {0}° it becomes huge. On the right, the graph with the poles and the most important relationships between sin, cos and tan.",
