"Rechenweg: Tangens": "Working: tangent",
"<0>Definition:</0> Der Tangens ist das Verhältnis von Sinus zu Kosinus, im rechtwinkligen Dreieck also Gegenkathete durch Ankathete. Im Einheitskreis ist {1} die <2>Steigung</2> des Strahls durch {3}: Er schneidet die senkrechte Tangente bei {4} in der Höhe {5}.": "<0>Definition:</0> The tangent is the ratio of sine to cosine, in the right-angled triangle therefore opposite divided by adjacent. In the unit circle, {1} is the <2>slope</2> of the ray through {3}: it meets the vertical tangent line at {4} at the height {5}.",
"<0>Werte bei</0> {1}:": "<0>Values at</0> {1}:",
"<0>Vorzeichen:</0> Sinus und Kosinus haben dasselbe Vorzeichen: {1} ({2}. Quadrant).": "<0>Signs:</0> Sine and cosine have the same sign: {1} (quadrant {2}).",
"<0>Definitionsbereich:</0> Der Tangens ist nicht definiert, wo der Kosinus {1} ist, also bei {2}, {3}, … Dort hat der Graph Polstellen.": "<0>Domain:</0> The tangent is not defined where the cosine is {1}, i.e. at {2}, {3}, … There the graph has poles.",
"<0>Periode:</0> Nach einer halben Drehung zeigt der Strahl in die Gegenrichtung; Sinus und Kosinus wechseln beide das Vorzeichen, ihr Quotient bleibt gleich. Der Tangens hat darum schon die Periode {1} (Sinus und Kosinus: {2}).": "<0>Period:</0> After half a turn the ray points in the opposite direction; sine and cosine both change sign, their quotient stays the same. That is why the tangent already has the period {1} (sine and cosine: {2}).",
"<0>Beziehungen zwischen den Funktionen:</0>": "<0>Relationships between the functions:</0>",
"<0>Probe mit den Werten:</0> {1}, {2}.": "<0>Check with the values:</0> {1}, {2}.",
"Der Tangens ist die Steigung des Strahls: {0}; Periode {1}, Polstellen bei {2}": "The tangent is the slope of the ray: {0}; period {1}, poles at {2}",
"<0>Vorzeichen:</0> Auf der {1}-Achse ist der Sinus {2}, also {3}.": "<0>Signs:</0> On the {1}-axis the sine is {2}, so {3}.",
"nicht definiert": "not defined",
"<0>Polstelle:</0> Der Strahl verläuft senkrecht und trifft die Tangente bei {1} nie. Nähert sich {2} dem Winkel {3}, wird {4} beliebig gross: Die Gerade {5} ist eine <6>senkrechte Asymptote</6>.": "<0>Pole:</0> The ray is vertical and never meets the tangent line at {1}. As {2} approaches the angle {3}, {4} becomes arbitrarily large: the line {5} is a <6>vertical asymptote</6>.",
"<0>Probe mit den Werten:</0> {1}.": "<0>Check with the values:</0> {1}.",
"Bei {0} hat der Tangens eine Polstelle; Periode {1}": "At {0} the tangent has a pole; period {1}",
"<0>Vorzeichen:</0> Sinus und Kosinus haben verschiedene Vorzeichen: {1} ({2}. Quadrant).": "<0>Signs:</0> Sine and cosine have different signs: {1} (quadrant {2}).",
"Umkehrfunktionen": "Inverse functions",
