"Rechenweg: Umkehrbarkeit": "Working: invertibility",
"<0>Kriterium:</0> Eine Funktion ist umkehrbar, wenn jeder Wert {1} <2>höchstens einmal</2> angenommen wird. Im Bild: Jede <3>waagrechte Gerade</3> {4} schneidet den Graphen höchstens einmal. Das ist sicher erfüllt, wenn {5} streng monoton ist.": "<0>Criterion:</0> A function is invertible if every value {1} is taken <2>at most once</2>. In the picture: every <3>horizontal line</3> {4} meets the graph at most once. This is certainly satisfied if {5} is strictly monotonic.",
"<0>Hier:</0> {1} ist auf dem ganzen Definitionsbereich streng monoton wachsend. Jede waagrechte Gerade trifft den Graphen höchstens einmal, also ist {2} <3>umkehrbar</3>.": "<0>Here:</0> {1} is strictly increasing on the whole domain. Every horizontal line meets the graph at most once, so {2} is <3>invertible</3>.",
