"<0>Hier:</0> {1} ist auf dem ganzen Definitionsbereich streng monoton fallend. Jede waagrechte Gerade trifft den Graphen höchstens einmal, also ist {2} <3>umkehrbar</3>.": "<0>Here:</0> {1} is strictly decreasing on the whole domain. Every horizontal line meets the graph at most once, so {2} is <3>invertible</3>.",
