"<0>Schreibweisen:</0> {1} (Funktionsgleichung), {2}, {3} (Zuordnungspfeil). Die Zahl {4} heisst <5>Argument</5> oder Stelle, {6} <7>Funktionswert</7>.": "<0>Notations:</0> {1} (function equation), {2}, {3} (mapping arrow). The number {4} is called the <5>argument</5> or input, {6} the <7>function value</7>.",
"<0>Punkte im Koordinatensystem:</0> Jede Zeile der Tabelle ist ein Punkt {1}: {2} nach rechts, {3} nach oben. Alle Punkte zusammen bilden den <4>Graphen</4> von {5}.": "<0>Points in the coordinate system:</0> Each row of the table is a point {1}: {2} to the right, {3} up. All the points together form the <4>graph</4> of {5}.",
"Zu jedem {0} gehört genau ein Funktionswert {1}; die Wertetabelle entsteht durch Einsetzen, der Graph aus den Punkten {2}": "To each {0} belongs exactly one function value {1}; the table of values is obtained by substitution, the graph from the points {2}",
"{0} Tippe eine Funktion ein und ziehe die Punkte im Bild. Oben links wählst du die Ansicht, rechts steht der Rechenweg.": "{0} Type in a function and drag the points in the diagram. Choose the view at the top left; the working is on the right.",
"Das konnte ich nicht lesen. Erlaubt ist ein Term in x, z.B. x^{0}-{1}x, {2}x+{3}, sqrt(x), {4}/x, {5}^x oder sin(x).": "I couldn't read that. Permitted is a term in x, e.g. x^{0}-{1}x, {2}x+{3}, sqrt(x), {4}/x, {5}^x or sin(x).",
"Über jeder Stelle x im Abstand h steht ein Balken bis zur Höhe {0}. Verkleinert man den Abstand, rücken die Balken zusammen; bei h → {1} werden ihre Enden zur Kurve: Das ist der Graph der Funktion.": "Above each input x at spacing h stands a bar up to the height {0}. If the spacing is reduced, the bars move closer together; as h → {1} their ends become the curve: that is the graph of the function.",
"Schiebe den Abstand h langsam gegen {0} oder starte die Animation. Mit den Kästchen zeigst du Werte, Koordinaten, nur Punkte oder die Kurve.": "Slide the spacing h slowly towards {0} or start the animation. With the checkboxes you show values, coordinates, only points or the curve.",
