"<0>Definitionsbereich</0> {1}: alle {2}, die man einsetzen darf. Hier geht die Rechnung für jedes {3} auf: {4}.": "<0>Domain</0> {1}: all {2} that may be substituted. Here the calculation works for every {3}: {4}.",
"<0>Wertebereich</0> {1}: alle Werte, die herauskommen. Im gezeigten Ausschnitt liegen die Werte zwischen {2} und {3}.": "<0>Range</0> {1}: all values that come out. In the section shown, the values lie between {2} and {3}.",
"<0>y-Achsenabschnitt:</0> Der Graph schneidet die {1}-Achse bei {2}:": "<0>y-intercept:</0> The graph crosses the {1}-axis at {2}:",
"<0>Nullstellen:</0> Stellen {1}, an denen {2} ist, der Graph schneidet dort die {3}-Achse.": "<0>Zeros:</0> Inputs {1} at which {2}; there the graph crosses the {3}-axis.",
"<0>Monotonie:</0> Wo der Graph von links nach rechts steigt, heisst {1} <2>steigend</2>, wo er fällt, <3>fallend</3>. Zwischen den Abschnitten liegen Hoch- und Tiefpunkte.": "<0>Monotonicity:</0> Where the graph rises from left to right, {1} is called <2>increasing</2>; where it falls, <3>decreasing</3>. Between the sections lie maximum and minimum points.",
"<0>Senkrechte-Geraden-Test:</0> Jede senkrechte Gerade {1} trifft den Graphen einer Funktion <2>höchstens einmal</2> – zu jedem {3} gehört ja nur ein Wert. Bei {4} ist das der Punkt {5}.": "<0>Vertical line test:</0> Every vertical line {1} meets the graph of a function <2>at most once</2> – after all, only one value belongs to each {3}. At {4} this is the point {5}.",
"Eine Kurve, die von einer senkrechten Geraden zweimal getroffen wird (z.B. ein Kreis), ist <0>kein</0> Funktionsgraph.": "A curve that is met twice by a vertical line (e.g. a circle) is <0>not</0> the graph of a function.",
"Definitionsbereich, Wertebereich, Nullstellen, y-Achsenabschnitt und Monotonie beschreiben den Graphen; jede Stelle hat genau einen Wert": "Domain, range, zeros, y-intercept and monotonicity describe the graph; each input has exactly one value",
"<0>Definitionsbereich</0> {1}: alle {2}, die man einsetzen darf. Hier gibt es Stellen, an denen die Rechnung nicht aufgeht (z.B. Division durch {3} oder Wurzel aus einer negativen Zahl): von -{4} bis -\\frac{5}{6}{7}{8}{9}{10} (im Bild).": "<0>Domain</0> {1}: all {2} that may be substituted. Here there are inputs at which the calculation fails (e.g. division by {3} or the root of a negative number): from -{4} to -\\frac{5}{6}{7}{8}{9}{10} (in the picture).",
"<0>Definitionsbereich</0> {1}: alle {2}, die man einsetzen darf. Hier gibt es Stellen, an denen die Rechnung nicht aufgeht (z.B. Division durch {3} oder Wurzel aus einer negativen Zahl): x={4} (im Bild).": "<0>Domain</0> {1}: all {2} that may be substituted. Here there are inputs at which the calculation fails (e.g. division by {3} or the root of a negative number): x={4} (in the picture).",
"<0>y-Achsenabschnitt:</0> Der Graph schneidet die {1}-Achse bei {2}: {3} ist nicht definiert.": "<0>y-intercept:</0> The graph crosses the {1}-axis at {2}: {3} is not defined.",
"<0>Nullstellen:</0> Stellen {1}, an denen {2} ist, der Graph schneidet dort die {3}-Achse. Im Ausschnitt gibt es keine.": "<0>Zeros:</0> Inputs {1} at which {2}; there the graph crosses the {3}-axis. In the section shown there are none.",
"<0>Senkrechte-Geraden-Test:</0> Jede senkrechte Gerade {1} trifft den Graphen einer Funktion <2>höchstens einmal</2> – zu jedem {3} gehört ja nur ein Wert. Bei {4} gibt es keinen Punkt (nicht definiert).": "<0>Vertical line test:</0> Every vertical line {1} meets the graph of a function <2>at most once</2> – after all, only one value belongs to each {3}. At {4} there is no point (not defined).",
