"Einstieg in den Funktionsbegriff: Zuordnung und Wertetabelle, aus Punkten wird der Graph, Definitions- und Wertebereich, Nullstellen, Monotonie, Anwendungen mit Einheiten": "Introduction to the concept of a function: mapping and table of values, from points to the graph, domain and range, zeros, monotonicity, applications with units",
"Was ist eine Funktion? Werte einsetzen, die Wertetabelle füllen und zusehen, wie aus Punkten ein Graph wird. Dazu Definitions- und Wertebereich.": "What is a function? Substitute values, fill in the table of values and watch points turn into a graph. Plus domain and range.",
"Unterthemen": "Subtopics",
"Das freie Werkzeug: eine beliebige Funktion eintippen und Nullstellen, Extrema, Ableitung und Stammfunktion untersuchen, Parameter mit Schiebern.": "The free tool: type in any function and examine zeros, extrema, derivative and antiderivative, with sliders for parameters.",
"Geraden verstehen und aufstellen: Steigung und y-Achsenabschnitt, Gerade durch zwei Punkte und Schnittpunkte. Dazu Anwendungen wie Tarife und Bewegungen.": "Understanding and setting up straight lines: slope and y-intercept, the line through two points and intersection points. Plus applications such as tariffs and motion.",
"Parameter und drei Formen, Scheitelpunkt und quadratische Ergänzung, Nullstellen und Diskriminante, Parabel und Gerade, Parabel aus Punkten, Optimierung (Preis, Umsatz, Gewinn)": "Parameters and three forms, vertex and completing the square, zeros and discriminant, parabola and line, parabola from points, optimisation (price, revenue, profit)",
"Parabeln in drei Formen: Scheitelpunkt und quadratische Ergänzung, Nullstellen mit der Lösungsformel, Parabel und Gerade. Alles lässt sich im Bild ziehen.": "Parabolas in three forms: vertex and completing the square, zeros with the quadratic formula, parabola and line. Everything can be dragged in the picture.",
"Optimierung: Preis, Umsatz, Gewinn": "Optimisation: price, revenue, profit",
"Von x² über {0}/x bis √x: wie der Exponent die Form des Graphen bestimmt, Wurzeln als Umkehrung und die allgemeine Form mit Strecken und Verschieben.": "From x² via {0}/x to √x: how the exponent determines the shape of the graph, roots as the inverse and the general form with stretching and shifting.",
"Wachstum und Zerfall a·b^x, die Zahl e, Logarithmus als Umkehrung, Exponentialgleichungen und Anwendungen (Zinseszins, Zerfall, Abkühlung), Prozentrechnung mit Faktoren": "Growth and decay a·b^x, the number e, the logarithm as the inverse, exponential equations and applications (compound interest, decay, cooling), percentages with factors",
"Wachstum und Zerfall mit a·bˣ, die Zahl e und der Logarithmus als Umkehrung. Exponentialgleichungen Schritt für Schritt, mit Zins und Zerfall.": "Growth and decay with a·bˣ, the number e and the logarithm as the inverse. Exponential equations step by step, with interest and decay.",
"Prozentrechnung: Faktor, rückwärts, mehrere Schritte": "Percentages: factor, backwards, several steps",
"Einheitskreis mit Sinus und Kosinus, Bogenmass, allgemeine Sinusfunktion a·sin({0})+d mit Amplitude, Periode und Verschiebung, Tangens mit Polstellen und Beziehungen, rechtwinkliges Dreieck (sin, cos, tan), Sinus- und Kosinussatz, Vermessung": "Unit circle with sine and cosine, radians, general sine function a·sin({0})+d with amplitude, period and shift, tangent with poles and identities, right-angled triangle (sin, cos, tan), sine and cosine rule, surveying",
"Sinus und Kosinus am Einheitskreis, Grad und Bogenmass. Die allgemeine Sinusfunktion mit Amplitude, Periode und Verschiebung, dazu der Tangens.": "Sine and cosine on the unit circle, degrees and radians. The general sine function with amplitude, period and shift, plus the tangent.",
"Rechtwinkliges Dreieck: sin, cos, tan": "Right-angled triangle: sin, cos, tan",
"Allgemeines Dreieck: Sinus- und Kosinussatz": "General triangle: sine and cosine rule",
"Umkehren heisst spiegeln an der Geraden y = x. Wann eine Funktion umkehrbar ist, wie man die Umkehrfunktion berechnet und welche Paare man kennen sollte.": "Inverting means reflecting in the line y = x. When a function is invertible, how to calculate the inverse function and which pairs you should know.",
"Grenzwerte von Funktionen, Differenzenquotient, Sekante und Tangente, Graphisches Ableiten, Ableitungsregeln, Kurvendiskussion, Extremwertprobleme, Polynom aus Bedingungen": "Limits of functions, difference quotient, secant and tangent, graphical differentiation, differentiation rules, curve sketching, optimisation problems, polynomial from conditions",
"Von der Sekante zur Tangente: Differenzenquotient und Ableitung, graphisches Ableiten, die Ableitungsregeln und eine vollständige Kurvendiskussion.": "From the secant to the tangent: difference quotient and derivative, graphical differentiation, the differentiation rules and a complete curve analysis.",
"Grenzwerte von Funktionen": "Limits of functions",
"Extremwertprobleme": "Optimisation problems",
"Polynom aus Bedingungen": "Polynomial from conditions",
"Ober- und Untersummen, Integralfunktion und Hauptsatz, Stammfunktion mit Regeln, partielle Integration und Substitution als Bild, Flächen zwischen Kurven, Rotationskörper": "Upper and lower sums, integral function and fundamental theorem, antiderivative with rules, integration by parts and substitution as a picture, areas between curves, solids of revolution",
"Flächen mit Rechtecken annähern, Integralfunktion und Hauptsatz, Stammfunktionen mit Regeln. Dazu Flächen zwischen Kurven und Rotationskörper.": "Approximating areas with rectangles, integral function and fundamental theorem, antiderivatives with rules. Plus areas between curves and solids of revolution.",
"Partielle Integration (Bild)": "Integration by parts (picture)",
"Substitution (Bild)": "Substitution (picture)",
"Folgen explizit und rekursiv, arithmetische und geometrische Folgen, Reihen und Summenzeichen, Grenzwert, unendliche geometrische Reihe, vollständige Induktion": "Sequences explicit and recursive, arithmetic and geometric sequences, series and sigma notation, limit, infinite geometric series, mathematical induction",
"Folgen explizit und rekursiv, arithmetisch und geometrisch, Reihen mit dem Summenzeichen, Grenzwerte und vollständige Induktion – alles als Punkte zum Ziehen.": "Sequences explicit and recursive, arithmetic and geometric, series with sigma notation, limits and mathematical induction – all as points you can drag.",
