"Intervalle auf der Zahlengeraden in drei Schreibweisen: als Intervall, als Ungleichung und in Mengenschreibweise. Dazu Schnittmenge, Vereinigung, Differenz und Komplement von zwei Intervallen.": "Intervals on the number line in three notations: as an interval, as an inequality and in set notation. Plus intersection, union, difference and complement of two intervals.",
