"Termumformungen als Bild: binomische Formeln, Ausmultiplizieren und Faktorisieren, Potenzen, Wurzeln und Logarithmen, Bruchterme und Gleichungen.": "Transforming terms as a picture: binomial formulae, expanding and factorising, powers, roots and logarithms, algebraic fractions and equations.",
"Konstruieren wie mit Zirkel und Lineal: Punkte, Geraden, Kreise und Dreiecke mit ihren besonderen Linien und Punkten.": "Constructing as with compass and ruler: points, lines, circles and triangles with their special lines and points.",
"Thema öffnen": "Open topic",
"Ähnlichkeit": "Similarity",
"Ein fixes Dreieck und sein Bild nach Verschiebung, Drehung um den Ursprung, Spiegelung an der x- oder y-Achse und zentrischer Streckung: Die Seitenverhältnisse stehen als Brüche daneben. Dazu Strahlensätze und das rechtwinklige Dreieck mit Höhe.": "A fixed triangle and its image after translation, rotation about the origin, reflection in the x- or y-axis and dilation: the side ratios are shown as fractions next to it. Plus the intercept theorems and the right-angled triangle with altitude.",
