"Vektorgeometrie im Raum: Ebenen entdecken, Punkte und Vektoren, Geraden, Skalarprodukt und Winkel, Abstände und Kugel. Den Raum drehst du mit der Maus.": "Vector geometry in space: discovering planes, points and vectors, lines, scalar product and angle, distances and sphere. You rotate the space with the mouse.",
