"Statistik und Stochastik rechnen": "Calculating statistics and probability",
"Statistik und Stochastik zum Rechnen: Kennwerte und Diagramme einer Datenreihe, Baumdiagramme, Binomial- und Normalverteilung, Erwartungswert und Hypothesentest, jeweils mit Rechenweg.": "Statistics and probability for calculating: key figures and charts of a data series, tree diagrams, binomial and normal distribution, expected value and hypothesis test, each with the working.",
