"Ungleichungen mit einer und zwei Variablen, Ungleichungssysteme und Planungspolygon, Zielfunktion, Niveaulinie und Optimum, Textaufgaben": "Inequalities with one and two variables, systems of inequalities and feasible region, objective function, level line and optimum, word problems",
"Vom Text zum Optimum: Ungleichungen als Halbebenen, Planungspolygon mit Eckpunkten und eine Niveaulinie, die du bis zum Optimum verschiebst.": "From the text to the optimum: inequalities as half-planes, feasible region with vertices and a level line that you shift to the optimum.",
