"Diese Startseite öffnest du jederzeit mit «Startseite» oben links, dem Logo oder dem Themenknopf in der Leiste. «Weiter mit …» oben rechts führt zurück zum zuletzt gewählten Thema.": "You can open this home page at any time with “Home” at the top left, the logo or the topic button in the bar. “Continue with …” at the top right takes you back to the topic you chose last.",
"Der Knopf «? Hilfe zum Thema» in der Leiste erklärt, was im aktuellen Thema und in der aktuellen Ansicht besonders ist.": "The button “? Help on this topic” in the bar explains what is special about the current topic and the current view.",
"Unterstrichene Wörter im Satz über dem Bild heben beim Darüberfahren die zugehörigen Teile im Bild hervor.": "Underlined words in the sentence above the picture highlight the corresponding parts of the picture when you hover over them.",
"Begriff der Umkehrfunktion (Spiegelung an y = x), Umkehrbarkeit und Einschränkung des Definitionsbereichs, Umkehrfunktion berechnen, bekannte Paare (x² und √x, {0}^x und log₂ x, sin und arcsin …)": "Concept of the inverse function (reflection in y = x), invertibility and restricting the domain, calculating the inverse function, well-known pairs (x² and √x, {0}^x and log₂ x, sin and arcsin …)",
"Intervalle auf der Zahlengeraden in drei Schreibweisen (Intervall, Ungleichung, Mengenschreibweise), Schnittmenge, Vereinigung, Differenz und Komplement": "Intervals on the number line in three notations (interval, inequality, set notation), intersection, union, difference and complement",
"Ähnlichkeitsabbildungen (Spiegeln, Drehen, Strecken, Verschieben), ähnliche Dreiecke, Seitenverhältnisse, Strahlensätze, rechtwinkliges Dreieck mit Höhe": "Similarity transformations (reflecting, rotating, stretching, shifting), similar triangles, side ratios, intercept theorems, right-angled triangle with altitude",
"Datenanalyse (Mittelwert, Median, Quartile, Standardabweichung, Boxplot, Histogramm), Baumdiagramm und Pfadregeln, Binomialverteilung, Poissonverteilung, Erwartungswert und faire Spiele, Normalverteilung, Grenzwerte (Binomial → Poisson, Normal) mit Herleitung, Hypothesentest": "Data analysis (mean, median, quartiles, standard deviation, box plot, histogram), tree diagram and path rules, binomial distribution, Poisson distribution, expected value and fair games, normal distribution, limits (binomial → Poisson, normal) with derivation, hypothesis test",
"Beliebige Funktionen zeichnen und untersuchen: Nullstellen, Extrema, Ableitung, Stammfunktion, Parameter mit Schiebern, Balken über den Stellen, Punkte setzen": "Draw and examine any function: zeros, extrema, derivative, antiderivative, parameters with sliders, bars above the x-values, placing points",
"{0}: gleiche Winkel, alle entsprechenden Seitenverhältnisse gleich {1}": "{0}: equal angles, all corresponding side ratios equal {1}",
"<0>Flächen</0> werden mit {1} multipliziert:": "<0>Areas</0> are multiplied by {1}:",
"<0>Seitenverhältnisse im Dreieck bleiben erhalten:</0> Teilt man zwei Seiten desselben Dreiecks, erhält man im Bild dasselbe wie im Original.": "<0>Side ratios within the triangle are preserved:</0> If you divide two sides of the same triangle, you get the same result in the image as in the original.",
"<0>Entsprechende Seiten:</0> Jede Länge wird mit dem gleichen Faktor {1} multipliziert. Das Verhältnis Bild : Original ist für alle drei Seiten gleich:": "<0>Corresponding sides:</0> Every length is multiplied by the same factor {1}. The ratio image : original is the same for all three sides:",
"<0>Winkel bleiben gleich:</0> Bei jeder Ähnlichkeitsabbildung sind entsprechende Winkel gleich gross.": "<0>Angles stay the same:</0> In every similarity transformation, corresponding angles are equal.",
"<0>Zusammenhang:</0> Punkt und Bildpunkt liegen auf einer Geraden durch {1}, und es gilt {2}. Entsprechende Seiten sind parallel.": "<0>Relationship:</0> A point and its image lie on a straight line through {1}, and {2} holds. Corresponding sides are parallel.",
"<0>Abbildung:</0> Zentrische Streckung von {1} aus mit {2}.": "<0>Transformation:</0> Dilation from {1} with {2}.",
