"Entsprechende Seiten: Bild : Original": "Corresponding sides: image : original",
"ABC": "ABC",
"Wähle links eine Abbildung und vergleiche das Bild {0} mit dem Original {1}: Verschiebung, Drehung um den Ursprung, Spiegelung an der x- oder y-Achse und zentrische Streckung lassen alle Winkel gleich, alle Seiten stehen im Verhältnis |k|.": "Choose a transformation on the left and compare the image {0} with the original {1}: translation, rotation about the origin, reflection in the x- or y-axis and dilation keep all angles equal, and all sides are in the ratio |k|.",
"{0} Ziehe die Ecken und die Griffe im Bild. Oben links wählst du die Ansicht, rechts steht der Rechenweg.": "{0} Drag the vertices and the handles in the picture. At the top left you choose the view; the working is on the right.",
"{0} mit Faktor {1}": "{0} with factor {1}",
"Die Dreiecke sind gleich orientiert: Drehen, Strecken und Verschieben genügen.": "The triangles have the same orientation: rotating, stretching and shifting are enough.",
"<0>Entsprechende Ecken in derselben Reihenfolge notieren</0>, dann sind die entsprechenden Seitenverhältnisse gleich:": "<0>Write corresponding vertices in the same order</0>, then the corresponding side ratios are equal:",
"<0>Gleiche Winkel gefunden:</0> Die Ecken mit gleichen Winkeln entsprechen sich:": "<0>Equal angles found:</0> The vertices with equal angles correspond to each other:",
"<0>Merke:</0> Zwei Dreiecke sind ähnlich, wenn sie in allen drei Winkeln übereinstimmen. Wegen der Winkelsumme {1} genügen zwei gleiche Winkel.": "<0>Remember:</0> Two triangles are similar if they agree in all three angles. Because of the angle sum {1}, two equal angles are enough.",
"gleich orientiert (ohne Spiegelung)": "same orientation (no reflection)",
