"Zwei Dreiecke (ABC und PQR) sind ähnlich, wenn sie in allen Winkeln übereinstimmen. Dann sind auch alle entsprechenden Seitenverhältnisse gleich. Gleiche Farben zeigen, welche Ecken und Seiten sich entsprechen.": "Two triangles (ABC and PQR) are similar if they agree in all angles. Then all corresponding side ratios are equal too. Equal colours show which vertices and sides correspond.",
"PQR": "PQR",
"Ziehe die Ecken von {0} und {1}: Stimmen alle Winkel überein, sind die Dreiecke ähnlich, und alle entsprechenden Seitenverhältnisse sind gleich. Gleiche Farben zeigen, was sich entspricht.": "Drag the vertices of {0} and {1}: if all angles agree, the triangles are similar and all corresponding side ratios are equal. Equal colours show what corresponds.",
"Beim zweiten Strahlensatz gehören zu den Parallelen immer die Abschnitte von {0} aus, nicht die Abschnitte {1} und {2}.": "In the second intercept theorem, the parallels always go with the segments measured from {0}, not with the segments {1} and {2}.",
"<0>Fehlende Länge berechnen:</0> Gesucht ist {1}, bekannt sind {2}, {3} und {4}. Verhältnisgleichung aufstellen und nach {5} auflösen:": "<0>Calculating a missing length:</0> We are looking for {1}; {2}, {3} and {4} are known. Set up the proportion and solve for {5}:",
"<0>Zweiter Strahlensatz:</0> Die Parallelen stehen im gleichen Verhältnis wie die Abschnitte von {1} aus.": "<0>Second intercept theorem:</0> The parallels are in the same ratio as the segments measured from {1}.",
"Ebenso die Abschnitte zwischen den Parallelen:": "Likewise the segments between the parallels:",
"<0>Erster Strahlensatz:</0> Die Abschnitte von {1} aus stehen auf beiden Strahlen im gleichen Verhältnis.": "<0>First intercept theorem:</0> The segments measured from {1} are in the same ratio on both rays.",
"<0>Ähnliche Dreiecke:</0> Weil {1}, stimmen {2} und {3} in allen Winkeln überein (gemeinsamer Winkel bei {4}, Stufenwinkel an Parallelen).": "<0>Similar triangles:</0> Because {1}, {2} and {3} agree in all angles (common angle at {4}, corresponding angles at parallels).",
"Zwei Strahlen haben den gemeinsamen Anfangspunkt {0}. {1} und {2} liegen auf dem einen, {3} und {4} auf dem anderen Strahl (V-Figur).": "Two rays have the common starting point {0}. {1} and {2} lie on one ray, {3} and {4} on the other (V-figure).",
"Fehlende Länge mit Verhältnisgleichung": "Missing length with a proportion",
"Abschnitte:": "Segments:",
"{0}. Strahlensatz": "Intercept theorem {0}",
"Längen anzeigen": "Show lengths",
"D frei ziehen (CD nicht parallel)": "Drag D freely (CD not parallel)",
"Lage von C und D": "Position of C and D",
"Nicht parallel (D frei)": "Not parallel (D free)",
"X-Figur (C hinter Z)": "X-figure (C beyond Z)",
"V-Figur, C zwischen Z und A": "V-figure, C between Z and A",
"V-Figur": "V-figure",
"Werden zwei Strahlen mit Anfangspunkt Z von zwei Parallelen geschnitten, so sind die Dreiecke ZAB und ZCD ähnlich. Daraus folgen die Strahlensätze.": "If two rays with starting point Z are cut by two parallels, the triangles ZAB and ZCD are similar. The intercept theorems follow from this.",
"Ziehe {0} und {1}: Zwei Parallelen schneiden die Strahlen aus Z, die Dreiecke ZAB und ZCD sind ähnlich – daraus folgen die Strahlensätze. Mit «D frei» siehst du, dass es ohne Parallelen nicht mehr stimmt.": "Drag {0} and {1}: two parallels cut the rays from Z, and the triangles ZAB and ZCD are similar – the intercept theorems follow from this. With “D free” you see that it no longer holds without parallels.",
"Vorgehen: gleiche Winkel markieren, ähnliche Dreiecke mit entsprechenden Ecken in derselben Reihenfolge notieren, Verhältnisgleichung aufstellen und lösen.": "Procedure: mark equal angles, write down similar triangles with corresponding vertices in the same order, set up the proportion and solve it.",
"Kontrolle mit Pythagoras:": "Check with Pythagoras:",
"<0>Kathetensatz</0> aus {1} bzw. {2}:": "<0>Leg theorem</0> from {1} and {2} respectively:",
"<0>Höhensatz</0> aus {1}:": "<0>Altitude theorem</0> from {1}:",
"Entsprechende Ecken in derselben Reihenfolge: {0} (Winkel {1}), {2} (rechter Winkel), {3} (Winkel {4}).": "Corresponding vertices in the same order: {0} (angle {1}), {2} (right angle), {3} (angle {4}).",
"<0>Drei Dreiecke in einem:</0> Die Höhe {1} teilt das rechtwinklige Dreieck {2} in zwei Teildreiecke. Alle drei haben die Winkel {3}, {4} und {5}, also gilt": "<0>Three triangles in one:</0> The altitude {1} divides the right-angled triangle {2} into two smaller triangles. All three have the angles {3}, {4} and {5}, so",
"Kathetensatz:": "Leg theorem:",
"Höhensatz:": "Altitude theorem:",
"gegenüber": "opposite",
"Höhenfusspunkt D": "Foot of the altitude D",
"Schräg liegend": "Tilted",
"|AD| = {0}, |DB| = {1}": "|AD| = {0}, |DB| = {1}",
"Gleichschenklig (|AD| = |DB|)": "Isosceles (|AD| = |DB|)",
"|AD| = {0}, |DB| = {1} (wie im Dossier {2} : {3})": "|AD| = {0}, |DB| = {1} (as in the handout {2} : {3})",
"Die Höhe CD teilt das rechtwinklige Dreieck ABC in zwei Teildreiecke. Alle drei Dreiecke haben die Winkel α, β und {0}° und sind deshalb ähnlich: ΔADC ∼ ΔCDB ∼ ΔACB.": "The altitude CD divides the right-angled triangle ABC into two smaller triangles. All three triangles have the angles α, β and {0}° and are therefore similar: ΔADC ∼ ΔCDB ∼ ΔACB.",
"Ziehe {0} auf dem Thaleskreis oder die Ecken {1} und {2}: Die Höhe CD teilt das rechtwinklige Dreieck in zwei Teildreiecke, alle drei sind ähnlich (Winkel α, β, {3}°). Rechts stehen sie in gleicher Lage nebeneinander.": "Drag {0} on Thales’ circle or the vertices {1} and {2}: the altitude CD divides the right-angled triangle into two smaller triangles, and all three are similar (angles α, β, {3}°). On the right they are shown side by side in the same position.",
"Winkel und Seitenlängen lassen sich links einblenden; rechts stehen die Seitenverhältnisse als Brüche.": "Angles and side lengths can be shown on the left; the side ratios are given as fractions on the right.",
"«Abbildung vorführen …» spielt einzelne Abbildungen ab; «⟲ Bild auf das Original legen» stellt den Anfang wieder her.": "“Demonstrate transformation …” plays individual transformations; “⟲ Put image on the original” restores the start.",
"«Mehrere nacheinander» verknüpft die Abbildungen in fester Reihenfolge: spiegeln, um O drehen, von Z aus strecken, verschieben.": "“Several in a row” combines the transformations in a fixed order: reflect, rotate about O, stretch from Z, shift.",
"Das Original ABC bleibt fest. Unter «Abbildung» wählst du genau eine Grundabbildung: Verschiebung, Drehung um den Ursprung, Spiegelung an der x- oder y-Achse oder zentrische Streckung von Z aus. Das Bild A′B′C′ zeigt dann nur diese eine Abbildung; du kannst es auch mit der Maus verschieben, drehen bzw. strecken.": "The original ABC stays fixed. Under “Transformation” you choose exactly one basic transformation: translation, rotation about the origin, reflection in the x- or y-axis or dilation from Z. The image A′B′C′ then shows only this one transformation; you can also shift, rotate or stretch it with the mouse.",
"Rechenweg:": "Working:",
"⟲ Zurücksetzen": "⟲ Reset",
"Alles in dieser Ansicht in den Anfangszustand zurücksetzen (Rückgängig ist möglich)": "Reset everything in this view to its initial state (undo is possible)",
