"<0>Zusammenhang:</0> Punkt und Bildpunkt liegen auf demselben Kreis um {1}, der Winkel {2} ist für jeden Punkt {3} (gegen den Uhrzeigersinn): {4}.": "<0>Relationship:</0> A point and its image lie on the same circle about {1}; the angle {2} is {3} for every point (anticlockwise): {4}.",
"<0>Abbildung:</0> Drehung um den Ursprung {1} um {2}.": "<0>Transformation:</0> Rotation about the origin {1} by {2}.",
"Drehung um": "Rotation by",
"Positiver Winkel: gegen den Uhrzeigersinn. Du kannst das Bild auch an einer Ecke drehen.": "Positive angle: anticlockwise. You can also rotate the image at a vertex.",
"Drehung um den Ursprung O": "Rotation about the origin O",
"Mit {0} sind Bild und Original sogar kongruent (deckungsgleich): Verschiebung, Drehung und Spiegelung ändern keine Länge. Erst die zentrische Streckung macht aus «kongruent» «ähnlich».": "With {0}, image and original are even congruent: translation, rotation and reflection do not change any length. Only the dilation turns “congruent” into “similar”.",
"<0>Zusammenhang:</0> Jeder Punkt wandert um dieselbe Strecke in dieselbe Richtung: {1}. Die Strecken {2} sind parallel und gleich lang.": "<0>Relationship:</0> Every point moves the same distance in the same direction: {1}. The segments {2} are parallel and equally long.",
"<0>Abbildung:</0> Verschiebung um {1} nach rechts und {2} nach oben.": "<0>Transformation:</0> Translation by {1} to the right and {2} upwards.",
"Verschiebung um": "Translation by",
"Du kannst das Bild auch mit der Maus verschieben.": "You can also move the image with the mouse.",
"Jede Ecke und ihr Bild liegen gleich weit von der y-Achse entfernt. Ziehe die Ecken von ABC.": "Each vertex and its image are the same distance from the y-axis. Drag the vertices of ABC.",
"<0>Zusammenhang:</0> Punkt und Bildpunkt liegen gleich weit von der Achse entfernt, ihre Verbindung steht senkrecht auf der Achse: {1}. Der Umlaufsinn kehrt sich um.": "<0>Relationship:</0> A point and its image are the same distance from the axis, and the line joining them is perpendicular to the axis: {1}. The orientation is reversed.",
"<0>Abbildung:</0> Spiegelung an der {1}-Achse.": "<0>Transformation:</0> Reflection in the {1}-axis.",
"-Achse": "-axis",
"Spiegelung an der": "Reflection in the",
"Spiegelachse": "Mirror axis",
"Jede Ecke und ihr Bild liegen gleich weit von der x-Achse entfernt. Ziehe die Ecken von ABC.": "Each vertex and its image are the same distance from the x-axis. Drag the vertices of ABC.",
"Für {0} liegt das Bild auf der anderen Seite von {1}; es gilt {2}. Der Fall {3} ist die Punktspiegelung.": "For {0} the image lies on the other side of {1}; {2} holds. The case {3} is the point reflection.",
"<0>Zusammenhang:</0> Punkt und Bildpunkt liegen auf einer Geraden durch {1}, und es gilt {2} (für {3} auf der anderen Seite von {4}). Entsprechende Seiten sind parallel.": "<0>Relationship:</0> A point and its image lie on a straight line through {1}, and {2} holds (for {3} on the other side of {4}). Corresponding sides are parallel.",
"<0>Abbildung:</0> Punktspiegelung an {1} ({2}).": "<0>Transformation:</0> Point reflection in {1} ({2}).",
"Punktspiegelung an": "Point reflection in",
"<0>Abbildung:</0> Das Dreieck {1} wird nacheinander abgebildet durch: Spiegelung an der {2}-Achse, dann Verschiebung um {3} nach rechts und {4} nach unten.": "<0>Transformation:</0> The triangle {1} is mapped successively by: reflection in the {2}-axis, then translation by {3} to the right and {4} downwards.",
"Reihenfolge: zuerst spiegeln, dann um O drehen, dann von Z aus strecken, zuletzt verschieben. Jetzt: Spiegelung, dann Verschiebung.": "Order: first reflect, then rotate about O, then stretch from Z, finally shift. Now: reflection, then translation.",
"<0>Abbildung:</0> Das Dreieck {1} wird nacheinander abgebildet durch: Drehung um den Ursprung {2} um {3}, dann zentrische Streckung von {4} aus mit {5}.": "<0>Transformation:</0> The triangle {1} is mapped successively by: rotation about the origin {2} by {3}, then dilation from {4} with {5}.",
