"<0>Abbildung:</0> keine (das Bild liegt auf dem Original).": "<0>Transformation:</0> none (the image lies on the original).",
"Bild = Original": "Image = original",
"Reihenfolge: zuerst spiegeln, dann um O drehen, dann von Z aus strecken, zuletzt verschieben. Jetzt: zentrische Streckung.": "Order: first reflect, then rotate about O, then stretch from Z, finally shift. Now: dilation.",
