"<0>Ähnliche Dreiecke:</0> Weil {1}, stimmen {2} und {3} in allen Winkeln überein (Scheitelwinkel bei {4}, Wechselwinkel an Parallelen).": "<0>Similar triangles:</0> Because {1}, {2} and {3} agree in all angles (vertically opposite angles at {4}, alternate angles at parallels).",
"Zwei Geraden schneiden sich in {0}. {1} und {2} liegen auf der einen, {3} und {4} auf der anderen Geraden, auf verschiedenen Seiten von {5} (X-Figur).": "Two straight lines intersect at {0}. {1} and {2} lie on one line, {3} and {4} on the other, on different sides of {5} (X-figure).",
"Die Verhältnisse sind verschieden, weil {0}": "The ratios are different because {0}",
