"Das Dreieck ABC bleibt fest. Sein Bild A′B′C′ entsteht durch Verschieben, Drehen um den Ursprung O, Spiegeln an der x- oder y-Achse und zentrisches Strecken von Z aus. Die ersten drei Abbildungen erhalten alle Längen (Bild und Original sind kongruent), die Streckung multipliziert jede Länge mit |k|. Die Winkel bleiben immer gleich.": "The triangle ABC stays fixed. Its image A′B′C′ is produced by shifting, rotating about the origin O, reflecting in the x- or y-axis and dilating from Z. The first three transformations preserve all lengths (image and original are congruent); the dilation multiplies every length by |k|. The angles always stay the same.",
