"Zwischen f und der x-Achse liegen von a bis b n gleich breite Rechtecke. Die Untersumme (grün) nimmt den kleinsten, die Obersumme (blau) den grössten Funktionswert jedes Streifens.": "Between f and the x-axis there are n rectangles of equal width from a to b. The lower sum (green) takes the smallest, the upper sum (blue) the largest function value of each strip.",
"Eine lineare Funktion {0} = m·x + q hat als Graph eine Gerade. Die Steigung m sagt, um wie viel y pro Schritt {1} nach rechts wächst, q ist der y-Achsenabschnitt.": "A linear function {0} = m·x + q has a straight line as its graph. The slope m tells you by how much y grows for each step of {1} to the right; q is the y-intercept.",
"Spiegelpunkt P′ zeigen": "Show mirror point P′",
"{0} Schritt für Schritt wachsen lassen": "{0} Let it grow step by step",
"{0} Graph an y = x umklappen": "{0} Flip the graph over y = x",
"{0}Folgen und Reihen{1}": "{0}Sequences and series{1}",
"Eine Folge ist eine durchnummerierte Liste von Zahlen a₁, a₂, a₃, … Explizit berechnet man jedes Glied direkt aus n, rekursiv aus dem Vorgänger. Die Glieder erscheinen als Punkte (n | aₙ).": "A sequence is a numbered list of numbers a₁, a₂, a₃, … Explicitly, each term is calculated directly from n; recursively, from its predecessor. The terms appear as points (n | aₙ).",
"Folge": "Sequence",
"Streichhölzer: aₙ = {0}n + {1}": "Matchsticks: aₙ = {0}n + {1}",
"Quadratzahlen: aₙ = n²": "Square numbers: aₙ = n²",
"aₙ = {0}/n": "aₙ = {0}/n",
"aₙ = (−{0})ⁿ": "aₙ = (−{0})ⁿ",
