"Die Zielfunktion Z = px + qy soll maximal oder minimal werden. Punkte mit gleichem Z liegen auf einer Niveaulinie. Das Optimum liegt in einem Eckpunkt (oder auf einer ganzen Kante).": "The objective function Z = px + qy is to become as large or as small as possible. Points with the same Z lie on a level line. The optimum lies at a vertex (or along a whole edge).",
