"Blickrichtung": "Viewing direction",
"Eine Ebene im Raum hat die Koordinatenform a·x + b·y + c·z = d. Der Normalenvektor (a | b | c) steht senkrecht auf ihr. Achsenabschnitte: zwei Koordinaten null setzen. Buchstaben in der Gleichung werden zu Schiebern.": "A plane in space has the coordinate form a·x + b·y + c·z = d. The normal vector (a | b | c) is perpendicular to it. Axis intercepts: set two coordinates to zero. Letters in the equation become sliders.",
"nur Punktdiagramm": "dot plot only",
