"Pfad": "Path",
"<0>{1}. Pfadregel (Produktregel):</0> Die Wahrscheinlichkeit eines Pfades ist das Produkt der Wahrscheinlichkeiten entlang des Pfades.": "<0>Path rule {1} (product rule):</0> The probability of a path is the product of the probabilities along the path.",
"In der Urne liegen {0} rote ({1}) und {2} blaue ({3}) Kugeln. Es wird {4}-mal <5>mit</5> Zurücklegen gezogen. Die Wahrscheinlichkeiten bleiben auf jeder Stufe gleich.": "The urn contains {0} red ({1}) and {2} blue ({3}) balls. {4} draws are made <5>with</5> replacement. The probabilities stay the same at every stage.",
"<0>Erwartungswert und Standardabweichung:</0> Im Mittel erwartet man {1} Treffer; die Werte streuen um {2}.": "<0>Expected value and standard deviation:</0> On average {1} successes are expected; the values scatter by about {2}.",
