"<0>Formel von Bernoulli:</0> Für genau {1} Treffer gibt es {2} Pfade, jeder mit der Wahrscheinlichkeit {3}.": "<0>Bernoulli’s formula:</0> For exactly {1} successes there are {2} paths, each with probability {3}.",
"Ein Versuch mit «Treffer» (Wahrscheinlichkeit {0}) und «Niete» wird {1}-mal unabhängig wiederholt (Bernoulli-Kette). {2} zählt die Treffer: {3}.": "A trial with “success” (probability {0}) and “failure” is repeated {1} times independently (Bernoulli chain). {2} counts the successes: {3}.",
