"Formel:": "Formula:",
"Die Poissonverteilung beschreibt, <0>wie oft ein Ereignis</0> in einem festen Zeitraum (oder auf einer Seite, einer Strecke, einer Fläche) eintritt, wenn die Ereignisse einzeln, unabhängig voneinander und im Mittel gleich häufig auftreten. {1} zählt die Ereignisse, {2} ist ihre <3>mittlere Anzahl</3>.": "The Poisson distribution describes <0>how often an event</0> occurs in a fixed period (or on a page, a stretch, an area) when the events occur singly, independently of one another and equally often on average. {1} counts the events, {2} is their <3>mean number</3>.",
