"<0>Faires Spiel:</0> Ein Spiel ist fair, wenn der Einsatz gleich dem Erwartungswert der Auszahlung ist. Dann gewinnt auf lange Sicht niemand.": "<0>Fair game:</0> A game is fair if the stake equals the expected value of the payout. Then nobody wins in the long run.",
"<0>Erwartungswert:</0> jeden Wert mit seiner Wahrscheinlichkeit gewichten und addieren. Er ist der Mittelwert der Auszahlung auf lange Sicht (der Schwerpunkt der Verteilung).": "<0>Expected value:</0> weight each value with its probability and add. It is the mean of the payout in the long run (the centre of gravity of the distribution).",
