"Die Glockenkurve ist symmetrisch: {0}. Linksseitig und rechtsseitig ergänzen sich zu {1}, innerhalb und ausserhalb ebenfalls. Merkzahlen beidseitig: {2} sowie {3}. Bei stetigen Grössen ist {4}, darum ist es egal, ob {5} oder {6} steht.": "The bell curve is symmetric: {0}. Left-sided and right-sided add up to {1}, as do inside and outside. Two-sided values worth remembering: {2} and {3}. For continuous quantities {4}, so it does not matter whether {5} or {6} is written.",
