"Kosten K = Kf + kv·x": "Costs K = Kf + kv·x",
"Nachfrage {0} = A − B·p": "Demand {0} = A − B·p",
"Hängt die Nachfrage linear vom Preis ab, {0} = A − B·p, so ist der Umsatz {1} = p·{2} eine nach unten geöffnete Parabel. Mit den Kosten K = Kf + kv·x (Fixkosten und variable Kosten pro Stück) ist auch der Gewinn {3} = {4} − {5} eine Parabel; ihr Scheitel ist das Gewinnmaximum.": "If demand depends linearly on the price, {0} = A − B·p, the revenue {1} = p·{2} is a parabola opening downwards. With the costs K = Kf + kv·x (fixed costs and variable costs per unit) the profit {3} = {4} − {5} is also a parabola; its vertex is the maximum profit.",
"Gewinnschwelle und Gewinngrenze": "break-even point and profit limit",
