"Preis p": "price p",
"Ziehe den {0} auf der Preisachse: Mit dem Preis sinkt die {1}. {2} und {3} sind Parabeln: Ihr Scheitel liefert den {4} bzw. den {5}, die Nullstellen von G die {6}.": "Drag the {0} on the price axis: as the price rises, the {1} falls. {2} and {3} are parabolas: their vertex gives the {4} and the {5} respectively, and the zeros of G give the {6}.",
"Bei «Optimierung» ziehst du den Preis p; Nachfrage, Umsatz und Gewinn reagieren sofort.": "In “Optimisation” you drag the price p; demand, revenue and profit respond immediately.",
"Bei «Nullstellen» wählst du das Verfahren (z. B. Mitternachtsformel), bei «Parabel und Gerade» die Aufgabe (Schnitt, Parabel aus Punkten …).": "In “Zeros” you choose the method (e.g. the quadratic formula), in “Parabola and line” the task (intersection, parabola from points …).",
"Links wählst du die Form der Eingabe: Standardform, Scheitelform oder Nullstellenform. Der Rechenweg rechnet sie ineinander um.": "On the left you choose the form of the input: standard form, vertex form or factored form. The working converts them into one another.",
"Je nach Ansicht lassen sich der Scheitel S, der rote Punkt a (Öffnung), der Achsenabschnitt c und die Nullstellen ziehen.": "Depending on the view, the vertex S, the red point a (opening), the y-intercept c and the zeros can be dragged.",
