"<0>Wertebereich</0> {1}: alle Werte, die {2} auf dem ganzen Definitionsbereich annimmt. Man findet ihn über den kleinsten und grössten Wert (Tief- und Hochpunkte) und über das Verhalten an den Rändern von {3}, bei Polstellen und für {4}; ein Wert, dem sich der Graph nur annähert, gehört nicht dazu.": "<0>Range</0> {1}: all values that {2} takes on the whole domain. You find it from the smallest and largest value (low and high points) and from the behaviour at the edges of {3}, at poles and for {4}; a value that the graph only approaches does not belong to it.",
"Hier kommt keine dieser Rechnungen mit {0} vor, also darf man jede Zahl einsetzen.": "None of these operations with {0} occurs here, so any number may be substituted.",
"<0>Definitionsbereich</0> {1}: alle {2}, die man in die Vorschrift einsetzen darf – für die ganze Funktion, nicht nur im Bild. Verboten ist, durch {3} zu teilen, die Wurzel aus einer negativen Zahl zu ziehen und den Logarithmus einer Zahl {4} zu bilden.": "<0>Domain</0> {1}: all {2} that may be substituted into the rule – for the whole function, not only in the picture. It is not allowed to divide by {3}, to take the root of a negative number or to take the logarithm of a number {4}.",
