"Ziehe die {0} auf und ab und zähle ihre Schnittpunkte mit dem {1}: Ist es nie mehr als einer, ist f umkehrbar. Sonst schränkt man den Definitionsbereich ein (rote Grenze r).": "Drag the {0} up and down and count its points of intersection with the {1}: if there is never more than one, f is invertible. Otherwise the domain is restricted (red bound r).",
"Wähle eine Funktion: Rechts wird y = {0} nach x aufgelöst, dann werden x und y vertauscht. Zur Probe ziehe {1} auf {2}: Der Spiegelpunkt {3} liegt auf {4}.": "Choose a function: on the right y = {0} is solved for x, then x and y are swapped. To check, drag {1} on {2}: the mirror point {3} lies on {4}.",
"Wähle ein Paar und ziehe den {0} auf {1}: Sein Spiegelpunkt {2} liegt auf {3} – erst f, dann f⁻¹ führt zum Ausgangswert zurück. Beachte die eingeschränkten Bereiche bei x², sin, cos und tan.": "Choose a pair and drag the {0} on {1}: its mirror point {2} lies on {3} – first f, then f⁻¹ leads back to the starting value. Note the restricted domains for x², sin, cos and tan.",
"Die Winkelhalbierende y = x und die Umkehrfunktion f⁻¹ lassen sich links ein- und ausblenden.": "The bisector y = x and the inverse function f⁻¹ can be shown and hidden on the left.",
"Bei «Umkehrbarkeit» ziehst du die waagrechte Gerade y = k und die rote Grenze r, die den Definitionsbereich einschränkt.": "In “Invertibility” you drag the horizontal line y = k and the red bound r that restricts the domain.",
"Die Funktion wählst du über «Beispiel wählen …» oder tippst sie ein (lineare Funktionen, Potenz-, Exponential- und Logarithmusfunktionen).": "You choose the function via “Choose an example …” or type it in (linear functions, power, exponential and logarithmic functions).",
