"Ziehe die Punkte bei x = {0} ({1}) und x = {2} ({3}): Bei jedem Schritt um {4} wird mit b multipliziert ({5}). Für b {6} {7} wächst der {8}, für {9} {10} b {11} {12} zerfällt er; vergleiche mit dem {13} – «{14} Schritt für Schritt wachsen lassen» baut beide nebeneinander auf.": "Drag the points at x = {0} ({1}) and x = {2} ({3}): at each step of {4} the value is multiplied by b ({5}). For b {6} {7} the {8} grows, for {9} {10} b {11} {12} it decays; compare with the {13} – “{14} Let it grow step by step” builds both up side by side.",
