"Berührpunkt T": "point of tangency T",
"Ziehe den {0} auf dem {1}: Die Steigung der {2} ist überall genau gleich dem Funktionswert. Bei {3} stimmt das nicht – nur die Basis e ≈ {4} hat diese Eigenschaft. «{5} Basis von {6} bis {7} gleiten lassen» hält genau dort an.": "Drag the {0} on the {1}: the slope of the {2} is everywhere exactly equal to the function value. For {3} this is not true – only the base e ≈ {4} has this property. “{5} Let the base slide from {6} to {7}” stops exactly there.",
"Winkelhalbierenden": "bisector",
"Ziehe den {0} auf der {1}: Sein Spiegelpunkt {2} an der {3} liegt auf dem {4}. log_b(y) ist der Exponent, mit dem man b potenzieren muss, um y zu erhalten.": "Drag the {0} on the {1}: its mirror point {2} in the {3} lies on the {4}. log_b(y) is the exponent to which b must be raised to obtain y.",
"Gerade y = c": "line y = c",
"Ziehe die {0} auf und ab: Die Lösung von a·bˣ + d = c ist die Stelle, an der sie den {1} schneidet. Rechts wird sie mit dem Logarithmus berechnet, bei Anwendungen auch gedeutet.": "Drag the {0} up and down: the solution of a·bˣ + d = c is the position at which it cuts the {1}. On the right it is calculated with the logarithm, and in applications also interpreted.",
"Gesamtveränderung:": "Total change:",
"Die Prozente heben sich nicht auf: {0} und {1} ergeben zusammen {2}.": "The percentages do not cancel out: {0} and {1} together give {2}.",
