"Eine <0>Zunahme</0> um {1} heisst «mal {2}», eine <3>Abnahme</3> um {4} heisst «mal {5}»:": "An <0>increase</0> of {1} means “times {2}”, a <3>decrease</3> of {4} means “times {5}”:",
"Prozente als Faktoren": "Percentages as factors",
