"Rückwärts: Grundwert gesucht": "Backwards: base value wanted",
"Vorwärts: neuer Wert gesucht": "Forwards: new value wanted",
"Richtung": "Direction",
"Eine Zunahme um p % bedeutet Multiplikation mit q = {0} + p/{1}, eine Abnahme mit q = {2} − p/{3}. Bei mehreren Veränderungen nacheinander werden die Faktoren multipliziert, nicht die Prozente addiert. Den Grundwert findet man, indem man den neuen Wert durch den Faktor teilt.": "An increase of p % means multiplying by q = {0} + p/{1}, a decrease by q = {2} − p/{3}. With several changes in a row the factors are multiplied; the percentages are not added. The base value is found by dividing the new value by the factor.",
"Gesamtfaktor": "overall factor",
"Säulen": "columns",
"Ziehe die {0} hoch oder runter (oder gib die Prozente ein): Jede Veränderung um p % ist eine Multiplikation mit dem {1} {2} ± p/{3}. Alle Faktoren zusammen ergeben den {4}; rückwärts teilt man den Endwert durch ihn.": "Drag the {0} up or down (or enter the percentages): each change of p % is a multiplication by the {1} {2} ± p/{3}. All factors together give the {4}; backwards you divide the final value by it.",
"Bei «Prozentrechnung» ziehst du die Säulen; «＋ Schritt» und «− Schritt» ändern die Anzahl Veränderungen, und du wählst vorwärts oder rückwärts.": "In “Percentage calculation” you drag the columns; “＋ Step” and “− Step” change the number of changes, and you choose forwards or backwards.",
"Bei «Exponentialgleichungen» wählst du links eine Anwendung (Zinseszins, Zerfall, Abkühlung …) oder eine freie Gleichung; die Gerade y = c lässt sich ziehen.": "In “Exponential equations” you choose an application on the left (compound interest, decay, cooling …) or a free equation; the line y = c can be dragged.",
"Die Punkte bei x = {0} (Anfangswert a) und x = {1} (Faktor b) legen die Funktion fest; «Basis e» schaltet auf die natürliche Basis um.": "The points at x = {0} (initial value a) and x = {1} (factor b) determine the function; “Base e” switches to the natural base.",
