"Ziehe den {0} auf dem Einheitskreis oder lass den Winkel drehen: Die Höhe sin φ zeichnet rechts die {1}, der waagrechte Abstand cos φ die {2}. Besondere Winkel wie {3}°, {4}° und {5}° liefern exakte Werte.": "Drag the {0} on the unit circle or let the angle rotate: on the right, the height sin φ draws the {1}, the horizontal distance cos φ the {2}. Special angles such as {3}°, {4}° and {5}° give exact values.",
