"Im rechtwinkligen Dreieck gilt bezogen auf einen spitzen Winkel α: sin α = Gegenkathete : Hypotenuse, cos α = Ankathete : Hypotenuse, tan α = Gegenkathete : Ankathete. Mit zwei bekannten Stücken (darunter eine Seite) berechnet man alle anderen; dazu kommen Pythagoras und α + β = {0}°.": "In a right-angled triangle, relative to an acute angle α: sin α = opposite : hypotenuse, cos α = adjacent : hypotenuse, tan α = opposite : adjacent. From two known parts (at least one of them a side) all the others can be calculated; Pythagoras and α + β = {0}° are used as well.",
"Ankathete": "Adjacent side",
"Gegenkathete": "Opposite side",
"Ziehe die Ecken {0} und {1}: Für den Winkel {2} ist a die {3}, b die {4} und c die {5}. sin α, cos α und tan α sind ihre Verhältnisse – sie hängen nur vom Winkel ab, nicht von der Grösse des Dreiecks. Wähle oben, was gegeben ist.": "Drag the vertices {0} and {1}: for the angle {2}, a is the {3}, b the {4} and c the {5}. sin α, cos α and tan α are their ratios – they depend only on the angle, not on the size of the triangle. Choose at the top what is given.",
"Mit dem Kosinussatz nach den Winkeln aufgelöst:": "Solved for the angles with the cosine rule:",
