"Im allgemeinen Dreieck gelten der Sinussatz a : sin α = b : sin β = c : sin γ und der Kosinussatz a² = b² + c² − {0}bc·cos α. Den Kosinussatz braucht man bei SSS und SWS, den Sinussatz bei WSW und SSW; bei SSW mit a {1} b kann es zwei Dreiecke geben.": "In any triangle the sine rule a : sin α = b : sin β = c : sin γ and the cosine rule a² = b² + c² − {0}bc·cos α hold. The cosine rule is needed for SSS and SAS, the sine rule for ASA and SSA; for SSA with a {1} b there can be two triangles.",
"übrigen Stücke": "remaining parts",
"gegeben": "given",
"Ziehe die Ecken {0}, {1} und {2} und wähle, was {3} ist: Die {4} berechnet der Rechenweg mit dem Sinus- oder Kosinussatz. Die Beispiele zeigen Aufgaben aus der Vermessung.": "Drag the vertices {0}, {1} and {2} and choose what is {3}: the working calculates the {4} with the sine or cosine rule. The examples show surveying problems.",
"Bei den Dreiecken wählst du links, was gegeben ist; danach rechnet der Rechenweg mit sin, cos, tan bzw. mit dem Sinus- oder Kosinussatz.": "For the triangles, choose on the left what is given; the working then calculates with sin, cos, tan or with the sine or cosine rule.",
"Bei der allgemeinen Sinusfunktion ziehst du den Startpunkt S, den Hochpunkt H und das Periodenende; «{0} Grundfunktion verwandeln» zeigt die Schritte einzeln.": "For the general sine function, drag the starting point S, the maximum H and the end of the period; “{0} Transform base function” shows the steps one by one.",
