"Die allgemeine Sinusfunktion {0} = a·sin({1}) + d entsteht aus sin x: a streckt (Amplitude |a|, Hochpunkt), b ändert die Periode T = {2}π/b (Periodenende), c verschiebt in x-Richtung (Phase), d in y-Richtung (Mittellinie y = d); Startpunkt {3}.": "The general sine function {0} = a·sin({1}) + d is obtained from sin x: a stretches (amplitude |a|, maximum), b changes the period T = {2}π/b (end of the period), c shifts in the x-direction (phase), d in the y-direction (midline y = d); starting point {3}.",
