"Ziehe den {0} oder klicke ins Bild: Unten zeigt die {1}, wie viel Fläche unter {2} von {3} bis x gesammelt ist. Ihre {4} ist an jeder Stelle {5} – das ist der Hauptsatz.": "Drag the {0} or click in the picture: below, the {1} shows how much area under {2} has been collected from {3} to x. Its {4} at every point is {5} – that is the fundamental theorem.",
"Stammfunktion F": "antiderivative F",
"Gib eine Funktion ein und ziehe {0} und {1}: Rechts wird die {2} mit den Integrationsregeln bestimmt und das Integral als {3} − {4} berechnet. Stammfunktionen unterscheiden sich nur um eine Konstante C.": "Enter a function and drag {0} and {1}: on the right, the {2} is found with the integration rules and the integral is calculated as {3} − {4}. Antiderivatives differ only by a constant C.",
