"Stammfunktion F einzeichnen": "Draw antiderivative F",
"Schar F + C zeigen (andere Konstanten)": "Show family F + C (other constants)",
"Je weiter rechts, desto kleiner ist h": "The further right, the smaller h",
"Abstand h der beiden Punkte von a": "Distance h of the two points from a",
"Stelle a": "Position a",
"x → ±∞ (für grosse x)": "x → ±∞ (for large x)",
"x → a (an einer Stelle)": "x → a (at a point)",
"Der Grenzwert lim {0} für x → a ist die Zahl, der sich {1} beliebig nähert, wenn x von links und von rechts gegen a geht – auch wenn f an der Stelle a selbst nicht definiert ist. Ergibt das Einsetzen {2}/{3}, kürzt man zuerst den gemeinsamen Faktor. Für x → ±∞ entscheiden die höchsten Potenzen.": "The limit lim {0} for x → a is the number that {1} approaches arbitrarily closely as x tends to a from the left and from the right – even if f is not defined at a itself. If substituting gives {2}/{3}, the common factor is cancelled first. For x → ±∞ the highest powers decide.",
"blauen Punkt": "blue point",
"orangen": "orange",
"Ziehe den {0} oder {1} gegen die Stelle {2} (oder drücke «{3} h → {4}»): Die Funktionswerte von links und rechts nähern sich dem {5}. Wähle «x → ±∞», um das Verhalten für grosse x und die waagrechte Asymptote zu sehen.": "Drag the {0} or {1} towards the position {2} (or press “{3} h → {4}”): the function values from the left and from the right approach the {5}. Choose “x → ±∞” to see the behaviour for large x and the horizontal asymptote.",
"Beide Grenzwerte sind gleich: {0} ist die Steigung der Tangente.": "Both limits are equal: {0} is the slope of the tangent.",
"<0>Von links</0> ({1}, {2} links von {3}):": "<0>From the left</0> ({1}, {2} to the left of {3}):",
"<0>Von rechts</0> ({1}, {2} rechts von {3}):": "<0>From the right</0> ({1}, {2} to the right of {3}):",
"Die Sekante geht durch {0} und {1}. Ihre Steigung ist der Differenzenquotient:": "The secant passes through {0} and {1}. Its slope is the difference quotient:",
