"Sekante": "Secant",
"Ziehe {0} langsam zu {1} (oder drücke «{2} h → {3}»): Die {4} durch P und Q dreht sich in die {5}, ihre Steigung {6} nähert sich der Ableitung f′(x₀). Mit {7} wechselst du die Stelle x₀.": "Drag {0} slowly towards {1} (or press “{2} h → {3}”): the {4} through P and Q turns into the {5}; its slope {6} approaches the derivative f′(x₀). With {7} you change the position x₀.",
