"Jetzt darf man einsetzen:": "Now one may substitute:",
"Zähler und Nenner werden {0}: <1>unbestimmter Ausdruck</1> {2}. Beide enthalten den Faktor {3}, den man kürzt:": "Numerator and denominator become {0}: <1>indeterminate form</1> {2}. Both contain the factor {3}, which is cancelled:",
"<0>Einsetzen</0> von {1} in Zähler und Nenner:": "<0>Substituting</0> {1} into numerator and denominator:",
