"Rechenweg: Grenzwert": "Working: Limit",
"An der Stelle {0} ist {1} nicht definiert.": "At {0}, {1} is not defined.",
"{0} Tangente wandern lassen": "{0} Let the tangent move",
"Oben der Graph von f, unten der Graph der Ableitung f′. Ziehe den Punkt: Die Höhe des unteren Punktes ist die Steigung der Tangente oben. Der Ausschnitt richtet sich nach den Nullstellen, Extrem- und Wendepunkten. Ziehen im Bild verschiebt ihn, Mausrad oder zwei Finger zoomen, ein Klick setzt die Stelle; «⟲ Ausschnitt» stellt ihn wieder her.": "At the top the graph of f, at the bottom the graph of the derivative f′. Drag the point: the height of the lower point is the slope of the tangent above. The view is chosen according to the zeros, extreme points and inflection points. Dragging in the picture moves it, the mouse wheel or two fingers zoom, a click sets the position; “⟲ View” restores it.",
"Hoch-, Tief- und Wendepunkten": "maxima, minima and inflection points",
"Ziehe den {0} entlang von {1} oder lass die Tangente wandern: Die Steigung der {2} oben ist die Höhe des Punktes auf {3} unten. An {4} rastet der Punkt ein, und die Animation wartet, bis du «{5} weiter» drückst.": "Drag the {0} along {1} or let the tangent move: the slope of the {2} at the top is the height of the point on {3} at the bottom. At {4} the point snaps in, and the animation waits until you press “{5} continue”.",
"An dieser Stelle ist die Funktion nicht definiert oder nicht ableitbar.": "At this point the function is not defined or not differentiable.",
"Normale": "Normal",
"Gib eine Funktion ein und ziehe den {0} auf dem {1}: Rechts wird f′(x) mit den Ableitungsregeln berechnet, daraus die Steigung und die Gleichung der {2} in P (optional auch {3} und {4}).": "Enter a function and drag the {0} on the {1}: on the right, f′(x) is calculated with the differentiation rules, and from it the slope and the equation of the {2} at P (optionally also the {3} and {4}).",
"Gib eine Funktion ein oder wähle ein Beispiel: Am {0} sind {1}, {2} und {3} markiert, rechts stehen alle Ergebnisse. Der Rechenweg zeigt Schritt für Schritt, wie man sie findet.": "Enter a function or choose an example: on the {0}, {1}, {2} and {3} are marked; all results are on the right. The working shows step by step how to find them.",
