"Extremwertprobleme löst man in fünf Schritten: Variable wählen, Nebenbedingung aufstellen, Zielfunktion mit nur einer Variablen und Definitionsbereich angeben, Ableitung null setzen, Art des Extremums prüfen und das Ergebnis deuten.": "Optimisation problems are solved in five steps: choose a variable, set up the constraint, state the objective function with only one variable and its domain, set the derivative to zero, check the type of extremum and interpret the result.",
"Optimum": "optimum",
"Wähle eine Situation und ziehe den {0} auf der {1} (oder ändere x): Das {2} zeigt die Figur zur Variablen {3}. Wo die {4} waagrecht wird, liegt das {5}. «{6} x durchlaufen lassen» fährt alle Möglichkeiten ab und zeichnet dabei die Zielfunktion.": "Choose a situation and drag the {0} on the {1} (or change x): the {2} shows the figure for the variable {3}. Where the {4} becomes horizontal lies the {5}. “{6} Let x run through” goes through all possibilities and draws the objective function as it does so.",
