"Papier falten: {0} mm, ·{1} (Ziel {2} m)": "Folding paper: {0} mm, ·{1} (target {2} m)",
"Bei einer geometrischen Folge ist der Quotient q benachbarter Glieder (a₁, a₂) konstant: aₙ = a₁·qⁿ⁻¹. Für q {0} {1} exponentielles Wachstum, für {2} {3} q {4} {5} Zerfall.": "In a geometric sequence the quotient q of neighbouring terms (a₁, a₂) is constant: aₙ = a₁·qⁿ⁻¹. For q {0} {1} exponential growth, for {2} {3} q {4} {5} decay.",
"Ziehe {0} und {1}: Der Quotient q bleibt von Glied zu Glied gleich – Wachstum für q {2} {3}, Zerfall für {4} {5} q {6} {7} ({8}). Mit der {9} suchst du, ab welchem Glied {10} sie überschritten wird.": "Drag {0} and {1}: the quotient q stays the same from term to term – growth for q {2} {3}, decay for {4} {5} q {6} {7} ({8}). With the {9} you look for the term {10} from which it is exceeded.",
"letzter": "last",
