"{0} heisst: Setze für die Laufvariable {1} nacheinander alle ganzen Zahlen von der <2>unteren Grenze</2> {3} bis zur <4>oberen Grenze</4> {5} in den <6>Summanden</6> {7} ein und addiere die Ergebnisse.": "{0} means: for the index {1}, substitute one after another all integers from the <2>lower limit</2> {3} to the <4>upper limit</4> {5} into the <6>summand</6> {7} and add the results.",
