"∑ {0}(k + {1}) für k = {2} … {3}": "∑ {0}(k + {1}) for k = {2} … {3}",
"∑ {0} für k = {1} … {2} (konstanter Summand)": "∑ {0} for k = {1} … {2} (constant summand)",
