"∑ ({0}k − {1}) für k = {2} … {3}: ungerade Zahlen": "∑ ({0}k − {1}) for k = {2} … {3}: odd numbers",
"∑ k für k = {0} … {1} (Gauss)": "∑ k for k = {0} … {1} (Gauss)",
"Das Summenzeichen ist eine Kurzschrift: ∑ von k = m bis n über aₖ bedeutet aₘ + aₘ₊₁ + … + aₙ. Die Laufvariable (meist k, i oder j) durchläuft alle ganzen Zahlen von der unteren bis zur oberen Grenze; es gibt n − m + {0} Summanden. Der Name der Laufvariablen spielt keine Rolle, und man kann den Index verschieben: ∑ von k = {1} bis {2} über (k − {3}) = ∑ von j = {4} bis {5} über j.": "The summation sign is a shorthand: ∑ from k = m to n of aₖ means aₘ + aₘ₊₁ + … + aₙ. The index (usually k, i or j) runs through all integers from the lower to the upper limit; there are n − m + {0} summands. The name of the index does not matter, and the index can be shifted: ∑ from k = {1} to {2} of (k − {3}) = ∑ from j = {4} to {5} of j.",
"Summand (Term in k)": "Summand (expression in k)",
"Laufvariable k": "index k",
"Summanden": "summand",
"obere Grenze": "upper limit",
"untere Grenze": "lower limit",
"Lies das Summenzeichen: Die {0} sagt, bei welchem k du beginnst, die {1}, wo du aufhörst. Den {2} rechnest du für jedes k aus und addierst alle. Ziehe im Bild die Grenzen m und n und die {3}: Der Balken von k leuchtet, oben steht sein Summand. «{4} k von m bis n laufen lassen» addiert die Summanden der Reihe nach.": "Read the summation sign: the {0} says at which k you start, the {1} where you stop. You work out the {2} for each k and add them all. In the picture, drag the limits m and n and the {3}: the bar of k lights up, with its summand above it. “{4} Let k run from m to n” adds the summands one after another.",
"<0>Trick von Gauss:</0> Die Summe vorwärts und rückwärts untereinander schreiben. Jede Spalte ergibt {1}, und es gibt {2} Spalten: {3}.": "<0>Gauss's trick:</0> write the sum forwards and backwards one below the other. Each column gives {1}, and there are {2} columns: {3}.",
"<0>Reihe</0> = Summe der ersten {1} Glieder. Mit dem Summenzeichen:": "<0>Series</0> = sum of the first {1} terms. With the summation sign:",
"<0>Gefragt:</0> Wie gross ist die Summe {1}?": "<0>Question:</0> How large is the sum {1}?",
"Der neunjährige Carl Friedrich Gauss sollte in der Schule alle natürlichen Zahlen von {0} bis {1} zusammenzählen.": "At school, nine-year-old Carl Friedrich Gauss was asked to add up all the natural numbers from {0} to {1}.",
