"Kinosaal: Plätze in {0} Reihen": "Cinema: seats in {0} rows",
"Gauss: {0} + {1} + … + {2}": "Gauss: {0} + {1} + … + {2}",
"Die Summe der ersten n Glieder heisst Reihe: sₙ = a₁ + … + aₙ. Arithmetisch: sₙ = n·(a₁ + aₙ)/{0} (Trick von Gauss), geometrisch: sₙ = a₁·(qⁿ − {1})/(q − {2}).": "The sum of the first n terms is called a series: sₙ = a₁ + … + aₙ. Arithmetic: sₙ = n·(a₁ + aₙ)/{0} (Gauss's trick), geometric: sₙ = a₁·(qⁿ − {1})/(q − {2}).",
"Glieder aₖ": "terms aₖ",
