"Ziehe den {0} im unteren Bild nach links oder rechts, um n zu ändern: Oben kommen {1} dazu oder fallen weg, unten wächst sₙ = a₁ + … + aₙ. Beim Gauss-Trick ergänzt die rückwärts gelesene Folge die Balken zu einem Rechteck («{2} Gauss-Trick als Bewegung» zeigt, wie sie sich umdreht).": "Drag the {0} in the lower picture to the left or right to change n: at the top, {1} are added or removed; at the bottom sₙ = a₁ + … + aₙ grows. In Gauss's trick the sequence read backwards completes the bars to a rectangle (“{2} Gauss's trick as a movement” shows how it turns round).",
"für alle": "for all",
"Je schmaler der Streifen, desto später beginnt er: Zu jedem {0} gibt es ein solches {1}. Wichtig: {2} und {3} für {4}.": "The narrower the strip, the later it begins: for every {0} there is such an {1}. Important: {2} and {3} for {4}.",
"<0>Streifen um den Grenzwert:</0> Für {1} liegen ab dem Glied {2} alle Glieder im Streifen {3}:": "<0>Strip around the limit:</0> For {1}, from the term {2} onwards all terms lie in the strip {3}:",
"Bei Brüchen Zähler und Nenner durch die höchste Potenz von {0} teilen; dann gehen Terme wie {1} gegen {2}.": "For fractions, divide numerator and denominator by the highest power of {0}; then terms such as {1} tend to {2}.",
"<0>Konvergent:</0> Für grosse {1} kommen die Glieder der Zahl {2} beliebig nahe.": "<0>Convergent:</0> For large {1} the terms come arbitrarily close to the number {2}.",
"Der ε-Streifen wird laufend schmaler (die Höhe des Bildes zoomt mit), und es werden so viele Glieder gezeigt, dass man sieht: Ab N liegen wieder alle im Streifen.": "The ε-strip keeps getting narrower (the height of the picture zooms with it), and enough terms are shown to see that from N onwards all of them lie in the strip again.",
