"Kommen die Glieder für grosse n einer Zahl beliebig nahe, ist das der Grenzwert. Zu jedem ε gibt es ein N, ab dem alle Glieder im ε-Streifen liegen. Eine unendliche geometrische Reihe hat für |q| {0} {1} den Wert a₁/({2} − q).": "If the terms come arbitrarily close to a number for large n, that number is the limit. For every ε there is an N from which all terms lie in the ε-strip. An infinite geometric series has, for |q| {0} {1}, the value a₁/({2} − q).",
"Der Streifen wird immer schmaler, und es kommen immer mehr Glieder dazu": "The strip becomes narrower and narrower, and more and more terms are added",
"ε-Streifen": "ε-strip",
"grünen Punkt ε": "green point ε",
"Ziehe den {0}, um den {1} um den {2} schmaler zu machen: Ab einem Index N liegen alle Glieder im Streifen – je kleiner ε, desto weiter rechts liegt N. Mit «{3} Animation: ε → {4}» wird der Streifen immer schmaler, und es kommen immer mehr Glieder dazu.": "Drag the {0} to make the {1} around the {2} narrower: from some index N onwards all terms lie in the strip – the smaller ε, the further right N lies. With “{3} Animation: ε → {4}” the strip becomes narrower and narrower, and more and more terms are added.",
"(Voraussetzung)": "(hypothesis)",
"{0} gilt für alle {1}.": "{0} holds for all {1}.",
"Kontrolle für {0}: linke Seite {1}, rechte Seite {2}.": "Check for {0}: left-hand side {1}, right-hand side {2}.",
"<0>Bild:</0> Der erste Dominostein fällt (Anfang), und jeder Stein stösst seinen Nachfolger um (Schritt) – also fallen alle.": "<0>Picture:</0> The first domino falls (base case), and each domino knocks over its successor (step) – so they all fall.",
"<0>Beweis:</0> Die ersten {1} Summanden durch die Voraussetzung ersetzen, dann umformen:": "<0>Proof:</0> Replace the first {1} summands using the hypothesis, then rearrange:",
