"Aussage wählen …": "Choose a statement …",
"Vollständige Induktion: Gilt die Aussage für n = {0} (Anfang) und folgt sie für n + {1}, wenn sie für n gilt (Schritt), dann gilt sie für alle n – wie bei fallenden Dominosteinen.": "Mathematical induction: if the statement holds for n = {0} (base case) and it follows for n + {1} whenever it holds for n (step), then it holds for all n – as with falling dominoes.",
"Wähle eine Aussage und lass mit «Schritt» die Dominosteine fallen: Gilt {0} und folgt aus {1} stets {2}, dann gilt die Aussage für alle n. Die letzte Aussage zeigt, warum Beispiele allein nichts beweisen.": "Choose a statement and let the dominoes fall with “Step”: if {0} holds and {2} always follows from {1}, then the statement holds for all n. The last statement shows why examples alone prove nothing.",
"Grenzwert: grünen Punkt ε ziehen oder «{0} Animation: ε → {1}» starten – der Streifen wird schmaler, und es kommen Glieder dazu.": "Limit: drag the green point ε or start “{0} Animation: ε → {1}” – the strip becomes narrower and terms are added.",
"Summenzeichen: Fährst du mit der Maus über die untere oder obere Grenze, leuchtet der zugehörige Summand auf.": "Summation sign: if you move the mouse over the lower or upper limit, the corresponding summand lights up.",
"Arithmetische und geometrische Folgen: a₁ und a₂ ziehen. Die rote Zielgerade t zeigt, welches Glied einen Wert erreicht.": "Arithmetic and geometric sequences: drag a₁ and a₂. The red target line t shows which term reaches a value.",
"Folge eingeben: explizit als Term in n (z. B. {0}n+{1}) oder rekursiv; die Art schaltest du links um.": "Entering a sequence: explicitly as an expression in n (e.g. {0}n+{1}) or recursively; you switch the type on the left.",
"Der Quotient benachbarter Glieder ist immer {0}: Die Folge ist <1>geometrisch</1>.": "The quotient of neighbouring terms is always {0}: the sequence is <1>geometric</1>.",
