"<0>Gefragt:</0> Wie dick ist das Papier nach {1} Faltungen?": "<0>Question:</0> How thick is the paper after {1} folds?",
"<0>Gefragt:</0> Wie viele Hölzer braucht man für {1} Quadrate? Für wie viele Quadrate reichen {2} Hölzer genau?": "<0>Question:</0> How many matches are needed for {1} squares? For how many squares are {2} matches exactly enough?",
"Keine natürliche Zahl: Kein Glied der Folge hat genau diesen Wert.": "Not a natural number: no term of the sequence has exactly this value.",
"<0>Gefragt:</0> Wie viele Bakterien sind es zu Beginn der {1}. Stunde? Ab welcher Stunde sind es mindestens {2}?": "<0>Question:</0> How many bacteria are there at the beginning of hour {1}? From which hour are there at least {2}?",
"Eine Bakterienkultur besteht zu Beginn aus {0} Bakterien und wächst pro Stunde um {1} %. {2} = Anzahl Bakterien zu Beginn der {3}-ten Stunde.": "A bacterial culture consists of {0} bacteria at the start and grows by {1} % per hour. {2} = number of bacteria at the beginning of the {3}-th hour.",
"<0>Ab welchem Glied</0> gilt {1}? Ungleichung mit dem Logarithmus lösen (Achtung: {2}, das Zeichen kehrt):": "<0>From which term</0> does {1} hold? Solve the inequality with the logarithm (note: {2}, the sign reverses):",
