"<0>Gefragt:</0> Wie viel ist nach {1} Halbwertszeiten noch vorhanden? Ab welchem Glied ist es höchstens noch {2} mg?": "<0>Question:</0> How much is left after {1} half-lives? From which term is it at most {2} mg?",
"Von einem radioaktiven Stoff sind anfangs {0} mg vorhanden. Nach jeder Halbwertszeit ist nur noch die Hälfte übrig. {1} = Menge in mg nach {2} Halbwertszeiten.": "Initially there are {0} mg of a radioactive substance. After each half-life only half is left. {1} = amount in mg after {2} half-lives.",
