"Ein Kinosaal hat in der ersten Reihe {0} Plätze, jede weitere Reihe hat {1} Plätze mehr.": "A cinema has {0} seats in the first row; each further row has {1} seats more.",
"<0>Herleitung:</0> {1} – fast alle Summanden heben sich weg: {2}.": "<0>Derivation:</0> {1} – almost all summands cancel: {2}.",
