"<0>Gefragt:</0> Wie viele Reiskörner liegen auf den ersten {1} Feldern zusammen?": "<0>Question:</0> How many grains of rice lie on the first {1} squares altogether?",
"Legende vom Schachbrett: Auf das erste Feld legt man {0} Reiskorn, auf jedes weitere Feld doppelt so viele wie auf das vorherige. Ein Schachbrett hat {1} Felder.": "Legend of the chessboard: {0} grain of rice is placed on the first square, and on each further square twice as many as on the previous one. A chessboard has {1} squares.",
