"Ein <0>Intervall</0> ist die Menge aller reellen Zahlen zwischen zwei Randpunkten. Eckige Klammer {1}: Randpunkt gehört dazu; runde Klammer {2}: gehört nicht dazu. Bei {3} ist die Klammer immer offen.": "An <0>interval</0> is the set of all real numbers between two endpoints. Square bracket {1}: the endpoint belongs to it; round bracket {2}: it does not. At {3} the bracket is always open.",
"Intervall und Schreibweisen": "Interval and notations",
"Rechenweg: Intervall": "Working: Interval",
"gefüllter Punkt: Rand gehört dazu, leerer Punkt: gehört nicht dazu": "filled point: endpoint belongs to it, empty point: does not",
"Mengenschreibweise:": "Set-builder notation:",
