"Ziehe die {0} auf der Zahlengeraden und lege links fest, ob sie {1} oder bis ±∞ reichen: Das {2} erscheint in Intervallschreibweise, als Ungleichung und in Mengenschreibweise.": "Drag the {0} on the number line and set on the left whether they {1} or extend to ±∞: the {2} appears in interval notation, as an inequality and in set-builder notation.",
"{0} Ziehe die Randpunkte im Bild. Links wählst du offen oder geschlossen, unendlich und die Operation; rechts steht der Rechenweg.": "{0} Drag the endpoints in the picture. On the left you choose open or closed, infinite and the operation; the working is on the right.",
"Alle Operationen auf einen Blick:": "All operations at a glance:",
"<0>Vorgehen:</0> Beide Intervalle untereinander auf der Zahlengeraden einzeichnen, die gesuchten Bereiche ablesen und bei jedem Randpunkt prüfen, ob er dazugehört.": "<0>Procedure:</0> Draw both intervals one below the other on the number line, read off the required parts and check for each endpoint whether it belongs.",
"Die <0>Schnittmenge</0> {1} enthält alle Zahlen, die in {2} <3>und</3> in {4} liegen.": "The <0>intersection</0> {1} contains all numbers that lie in {2} <3>and</3> in {4}.",
