"Operation": "Operation",
"Mit Intervallen rechnet man wie mit Mengen: A ∩ B (und), A ∪ B (oder), A \\ B (ohne) und das Komplement Ā (alle anderen reellen Zahlen). Am einfachsten zeichnet man beide Intervalle untereinander und liest das Ergebnis ab; an jedem Randpunkt entscheidet man, ob er dazugehört.": "Intervals are handled like sets: A ∩ B (and), A ∪ B (or), A \\ B (without) and the complement Ā (all other real numbers). The easiest way is to draw both intervals one below the other and read off the result; at each endpoint one decides whether it belongs.",
"Ergebnismenge": "result set",
"Ziehe die Randpunkte von {0} und {1} und wähle eine Operation: Die {2} zeigt, welche Zahlen in A und B liegen (Schnittmenge), in A oder B (Vereinigung), in A, aber nicht in B (Differenz) oder nicht in A (Komplement).": "Drag the endpoints of {0} and {1} and choose an operation: the {2} shows which numbers lie in A and B (intersection), in A or B (union), in A but not in B (difference) or not in A (complement).",
