"Vereinigung A ∪ B: in A oder B. Schnitt A ∩ B: in A und B. Differenz A \\ B: in A, aber nicht in B. Komplement Ā: in G, aber nicht in A. Bei drei Mengen gibt es acht Felder; man füllt sie von der Mitte nach aussen. Gesetze von De Morgan: (A ∪ B)‾ = Ā ∩ B̄ und (A ∩ B)‾ = Ā ∪ B̄.": "Union A ∪ B: in A or B. Intersection A ∩ B: in A and B. Difference A \\ B: in A but not in B. Complement Ā: in G but not in A. With three sets there are eight regions; they are filled from the centre outwards. De Morgan's laws: (A ∪ B)‾ = Ā ∩ B̄ and (A ∩ B)‾ = Ā ∪ B̄.",
"Grundmenge G": "universal set G",
"Feldern": "regions",
"schraffierten Felder": "shaded regions",
"Wähle links eine Operation oder tippe einen Term wie (A ∪ B) ∩ C: Die {0} bilden die Ergebnismenge («{1} Term Schritt für Schritt schraffieren» baut sie von innen nach aussen auf). Mit Elementen oder Anzahlen in den {2} liest du das Ergebnis direkt ab; die Mengen {3}, {4} und {5} liegen in der {6}.": "Choose an operation on the left or type an expression such as (A ∪ B) ∩ C: the {0} form the result set (“{1} Shade the expression step by step” builds it up from the inside out). With elements or counts in the {2} you read off the result directly; the sets {3}, {4} and {5} lie in the {6}.",
"Tipp: Zuerst die Klammern. Ein Feld gehört dazu, wenn seine Punkte die Bedingung erfüllen.": "Tip: brackets first. A region belongs to the set if its points satisfy the condition.",
"Schraffiere": "Shade",
"Auswahl löschen": "Clear selection",
"Klicke im Bild auf ein Feld, um es zu schraffieren; nochmals klicken entfernt die Schraffur.": "Click on a region in the picture to shade it; clicking again removes the shading.",
"Schraffiere {0}: Klicke im Venn-Diagramm die Felder an.": "Shade {0}: click on the regions in the Venn diagram.",
