"Aufgabe": "Task",
"Übungen zu Intervallen (Schreibweisen, Schnitt, Vereinigung, Differenz, Komplement) und zu Mengenoperationen mit zwei oder drei Mengen im Venn-Diagramm. Jede Aufgabe wird neu erzeugt; «Lösung zeigen» zeigt den Weg.": "Exercises on intervals (notations, intersection, union, difference, complement) and on set operations with two or three sets in the Venn diagram. Each task is generated afresh; “Show solution” shows the method.",
"Venn-Diagramm": "Venn diagram",
"Wähle links die Aufgabenart und löse die Aufgabe: Tippe die Antwort ein oder klicke im {0} die Felder an, die zur Menge gehören. «Prüfen» zeigt, ob es stimmt; danach steht rechts der Lösungsweg.": "Choose the type of task on the left and solve it: type the answer or click in the {0} on the regions that belong to the set. “Check” shows whether it is right; afterwards the solution is on the right.",
"Übungen: Aufgabenart wählen, Antwort eintippen oder Felder anklicken, dann «Prüfen». «Lösung zeigen» und «Neue Aufgabe» stehen daneben.": "Exercises: choose the type of task, type the answer or click on regions, then “Check”. “Show solution” and “New task” are next to it.",
"Venn-Diagramm: Operation wählen oder einen eigenen Term mit den Tasten A, B, ∪, ∩, \\ und Ā eingeben; {0} oder {1} Mengen, Felder mit Elementen oder Anzahlen.": "Venn diagram: choose an operation or enter your own expression with the keys A, B, ∪, ∩, \\ and Ā; {0} or {1} sets, regions with elements or counts.",
"Die Schreibweise offener Intervalle ist wählbar: runde Klammer (a, b) oder nach aussen gedrehte eckige Klammer.": "The notation for open intervals can be chosen: round bracket (a, b) or square bracket turned outwards.",
