"Ein <0>Intervall</0> ist die Menge aller reellen Zahlen zwischen zwei Randpunkten. Eckige Klammer {1}: Randpunkt gehört dazu; nach aussen gedreht {2}: gehört nicht dazu. Bei {3} ist die Klammer immer offen.": "An <0>interval</0> is the set of all real numbers between two endpoints. Square bracket {1}: the endpoint belongs to it; turned outwards {2}: it does not. At {3} the bracket is always open.",
