"Gib links die Geraden g und h in Parameterform ein und drehe den Raum: Schneiden sie sich im {0}, sind sie parallel oder {1}? Die {2} entscheiden zuerst. Mit den Reglern t und s (oder «{3} t und s laufen lassen») wandern die Punkte {4} und {5} auf den Geraden: Jeder Parameterwert gibt genau einen Punkt.": "Enter the lines g and h in parametric form on the left and rotate the space: do they intersect at the {0}, are they parallel or {1}? The {2} decide first. With the sliders t and s (or “{3} Let t and s run”) the points {4} and {5} move along the lines: each parameter value gives exactly one point.",
"Gerade in Parameterform: X = P + t·u mit Stützpunkt P und Richtungsvektor u. Zwei Geraden sind identisch, echt parallel, schneidend oder windschief. Prüfen: Sind u und v Vielfache? Sonst gleichsetzen: zwei Gleichungen lösen, die dritte prüfen.": "Line in parametric form: X = P + t·u with support point P and direction vector u. Two lines are identical, strictly parallel, intersecting or skew. Check: are u and v multiples of each other? Otherwise equate: solve two equations and check the third.",
