"Gib links die Vektoren a und b ein und drehe den Raum: Der {0} zwischen ihnen folgt aus dem Skalarprodukt. Ist a · b = {1}, stehen sie senkrecht. Das {2} steht senkrecht auf beiden.": "Enter the vectors a and b on the left and rotate the space: the {0} between them follows from the dot product. If a · b = {1}, they are perpendicular. The {2} is perpendicular to both.",
"Skalarprodukt: a · b = a₁b₁ + a₂b₂ + a₃b₃ = |a|·|b|·cos φ. Daraus der Winkel: cos φ = a · b / (|a|·|b|). Senkrecht genau dann, wenn a · b = {0}. Vektorprodukt a × b: senkrecht zu a und b, Länge = Fläche des Parallelogramms.": "Dot product: a · b = a₁b₁ + a₂b₂ + a₃b₃ = |a|·|b|·cos φ. From this the angle: cos φ = a · b / (|a|·|b|). Perpendicular exactly when a · b = {0}. Cross product a × b: perpendicular to a and b, length = area of the parallelogram.",
