"<0>Planungspolygon</0> = Durchschnitt aller Halbebenen. Seine <1>Eckpunkte</1> sind Schnittpunkte von je zwei Grenzgeraden:": "<0>Feasible region</0> = intersection of all half-planes. Its <1>vertices</1> are intersections of two boundary lines each:",
