"Mehrere Ungleichungen gleichzeitig: Die Lösungsmenge ist der Durchschnitt der Halbebenen, das Planungspolygon. Seine Eckpunkte sind Schnittpunkte von zwei Grenzgeraden.": "Several inequalities at once: the solution set is the intersection of the half-planes, the feasible region. Its vertices are intersections of two boundary lines.",
"Planungspolygon": "Feasible region",
"Gib die Ungleichungen ein (eine pro Zeile) und ziehe den {0}: Er ist zulässig, wenn er im {1} liegt, dem Durchschnitt aller Halbebenen. Die Eckpunkte sind Schnittpunkte von zwei Grenzgeraden.": "Enter the inequalities (one per line) and drag the {0}: it is feasible if it lies in the {1}, the intersection of all half-planes. The vertices are intersections of two boundary lines.",
"Zielfunktion: «Maximum» oder «Minimum» wählen, dann die Niveaulinie ziehen oder «Niveaulinie zum Optimum» drücken.": "Objective function: choose “Maximum” or “Minimum”, then drag the level line or press “Level line to the optimum”.",
