"<0>Variablen:</0> {1} = Anzahl Tische, {2} = Anzahl Stühle": "<0>Variables:</0> {1} = number of tables, {2} = number of chairs",
"<0>Gefragt:</0> Wie viele Tische und Stühle soll die Schreinerei pro Woche herstellen, damit der Gewinn möglichst gross ist?": "<0>Question:</0> How many tables and chairs should the joinery make per week so that the profit is as large as possible?",
"Eine Schreinerei stellt Tische und Stühle her. Ein Tisch braucht {0} Stunden Zuschnitt und {1} Stunden Montage, ein Stuhl {2} Stunden Zuschnitt und {3} Stunden Montage. Pro Woche stehen {4} Stunden für den Zuschnitt und {5} Stunden für die Montage zur Verfügung. Ein Tisch bringt {6} CHF Gewinn, ein Stuhl {7} CHF.": "A joinery makes tables and chairs. A table needs {0} hours of cutting and {1} hours of assembly, a chair {2} hours of cutting and {3} hours of assembly. Per week, {4} hours are available for cutting and {5} hours for assembly. A table yields a profit of {6} CHF, a chair {7} CHF.",
"<0>Variablen:</0> {1} = Anzahl Wagen A, {2} = Anzahl Wagen B (pro Tag)": "<0>Variables:</0> {1} = number of cars A, {2} = number of cars B (per day)",
"<0>Gefragt:</0> Wie viele Wagen jedes Modells sollen pro Tag gebaut werden, damit der Reingewinn möglichst gross ist?": "<0>Question:</0> How many cars of each model should be built per day so that the net profit is as large as possible?",
"Ein Automobilwerk baut die Modelle A und B. Die Lackiererei schafft pro Tag höchstens {0} Wagen A und höchstens {1} Wagen B, das Montageband insgesamt höchstens {2} Wagen. Ein Wagen A bringt {3} CHF Reingewinn, ein Wagen B {4} CHF.": "A car plant builds the models A and B. The paint shop can handle at most {0} cars A and at most {1} cars B per day, the assembly line at most {2} cars in total. A car A yields a net profit of {3} CHF, a car B {4} CHF.",
"zulässig": "feasible",
"<0>Variablen:</0> {1} = Pakete Mischung A, {2} = Pakete Mischung B": "<0>Variables:</0> {1} = packets of blend A, {2} = packets of blend B",
"<0>Gefragt:</0> Wie viele Pakete jeder Mischung soll er abfüllen, damit der Gewinn möglichst gross ist?": "<0>Question:</0> How many packets of each blend should he fill so that the profit is as large as possible?",
"Ein Kaffeehändler mischt aus drei Kaffeesorten zwei Mischungen. Ein Paket Mischung A enthält {0} kg Sorte I, {1} kg Sorte II und {2} kg Sorte III, ein Paket Mischung B {3} kg Sorte I, {4} kg Sorte II und {5} kg Sorte III. An Lager sind {6} kg Sorte I, {7} kg Sorte II und {8} kg Sorte III. Ein Paket A bringt {9} CHF Gewinn, ein Paket B {10} CHF.": "A coffee merchant makes two blends from three kinds of coffee. A packet of blend A contains {0} kg of kind I, {1} kg of kind II and {2} kg of kind III; a packet of blend B contains {3} kg of kind I, {4} kg of kind II and {5} kg of kind III. In stock are {6} kg of kind I, {7} kg of kind II and {8} kg of kind III. A packet A yields a profit of {9} CHF, a packet B {10} CHF.",
"<0>Variablen:</0> {1} = Anzahl Einfamilienhäuser, {2} = Anzahl Mehrfamilienhäuser": "<0>Variables:</0> {1} = number of single-family houses, {2} = number of multi-family houses",
"<0>Gefragt:</0> Wie viele Häuser jeder Art sollen gebaut werden, damit der Gewinn möglichst gross ist?": "<0>Question:</0> How many houses of each kind should be built so that the profit is as large as possible?",
"Ein Architekturbüro plant Einfamilienhäuser (EFH) und Mehrfamilienhäuser (MFH). Ein EFH braucht {0} m² Bauland und kostet {1} {2} CHF, ein MFH braucht {3} m² Bauland und kostet {4} {5} {6} CHF. Zur Verfügung stehen {7} {8} m² Bauland und {9} Mio. CHF Kapital. Ein EFH bringt {10} {11} CHF Gewinn, ein MFH {12} {13} CHF.": "An architecture firm is planning single-family houses (EFH) and multi-family houses (MFH). An EFH needs {0} m² of building land and costs {1} {2} CHF; an MFH needs {3} m² of building land and costs {4} {5} {6} CHF. Available are {7} {8} m² of building land and {9} million CHF of capital. An EFH yields a profit of {10} {11} CHF, an MFH {12} {13} CHF.",
"Das Gebiet ist <0>nicht beschränkt</0> (es reicht ins Unendliche).": "The region is <0>unbounded</0> (it extends to infinity).",
"<0>Variablen:</0> {1}, {2} = Mengen der beiden Futtersorten (kg)": "<0>Variables:</0> {1}, {2} = amounts of the two kinds of feed (kg)",
"<0>Gefragt:</0> Wie viele kg jeder Sorte soll er mischen, damit das Futter möglichst wenig kostet?": "<0>Question:</0> How many kg of each kind should he mix so that the feed costs as little as possible?",
"Ein Bauer mischt zwei Futtersorten. {0} kg Sorte {1} enthält {2} Einheiten Eiweiss und {3} Einheit Vitamine, {4} kg Sorte {5} enthält {6} Einheit Eiweiss und {7} Einheiten Vitamine. Die Tiere brauchen pro Tag mindestens {8} Einheiten Eiweiss und {9} Einheiten Vitamine. Sorte {10} kostet {11} CHF pro kg, Sorte {12} kostet {13} CHF pro kg.": "A farmer mixes two kinds of feed. {0} kg of kind {1} contains {2} units of protein and {3} unit of vitamins; {4} kg of kind {5} contains {6} unit of protein and {7} units of vitamins. The animals need at least {8} units of protein and {9} units of vitamins per day. Kind {10} costs {11} CHF per kg, kind {12} costs {13} CHF per kg.",
"<0>Variablen:</0> Computerhersteller, beide Modelle bringen je {1} CHF": "<0>Variables:</0> computer manufacturer, both models yield {1} CHF each",
"<0>Gefragt:</0> Gibt es nur eine beste Lösung?": "<0>Question:</0> Is there only one best solution?",
