"Marchzins: Zeitstrahl und Konten": "Pro-rata interest: timeline and accounts",
"Trage links jede {0} mit ihrem Datum ein: Jede liegt auf einem {1} und trägt Marchzins bis zum {2}. Die {3} zeigt Zinstage und Zins je Konto, am Schluss werden {4}. «{5} Zinsen wachsen lassen» zeigt, wie der Zins Tag für Tag dazukommt.": "On the left, enter each {0} with its date: each one sits on its {1} and earns pro-rata interest until the {2}. The {3} shows interest days and interest per account; at the end, {4}. “{5} Let interest grow” shows how interest is added day by day.",
"Ein- oder Auszahlung": "deposit or withdrawal",
"eigenen Konto": "own account",
"Stichtag": "closing date",
"Tabelle": "table",
"Kapital und Zinsen addiert": "capital and interest are added",
"Prinzip der verschiedenen Konti beim Marchzins: Der Saldo am Jahresanfang und jede Ein- oder Auszahlung werden wie ein eigenes Konto behandelt. Jedes trägt Zins für seine Zinstage bis zum Stichtag (Monat = {0} Tage, Jahr = {1} Tage). Eine Auszahlung zählt als Konto mit negativem Betrag, ihr Zins wird abgezogen. Kapital und Zinsen zusammen ergeben den Saldo am Stichtag.": "Principle of separate accounts for pro-rata interest: the balance at the start of the year and each deposit or withdrawal are treated like a separate account. Each earns interest for its interest days until the closing date (month = {0} days, year = {1} days). A withdrawal counts as an account with a negative amount; its interest is subtracted. Capital and interest together give the balance on the closing date.",
"Saldo am Jahresanfang (CHF)": "Balance at the start of the year (CHF)",
