"<0>Konjugierte Zahl:</0> {1} hat denselben Realteil und den entgegengesetzten Imaginärteil. Das Produkt {2} ist reell.": "<0>Conjugate:</0> {1} has the same real part and the opposite imaginary part. The product {2} is real.",
"<0>Polarform:</0> Mit dem Betrag {1} und dem Winkel {2} gilt {3} und {4}.": "<0>Polar form:</0> With modulus {1} and angle {2} we have {3} and {4}.",
"<0>Argument:</0> Der Winkel {1} wird von der positiven reellen Achse aus im Gegenuhrzeigersinn gemessen. Der Taschenrechner liefert aus {2} nur Winkel zwischen {3} und {4}; der Quadrant von {5} entscheidet, was dazukommt.": "<0>Argument:</0> The angle {1} is measured counterclockwise from the positive real axis. From {2} a calculator only returns angles between {3} and {4}; the quadrant of {5} decides what has to be added.",
"<0>Betrag:</0> Der Zeiger ist die Hypotenuse eines rechtwinkligen Dreiecks mit den Katheten {1} und {2} (Satz des Pythagoras).": "<0>Modulus:</0> The arrow is the hypotenuse of a right triangle with legs {1} and {2} (Pythagorean theorem).",
"<0>Normalform:</0> {1} mit dem Realteil {2} und dem Imaginärteil {3}; für die imaginäre Einheit gilt {4}.": "<0>Algebraic form:</0> {1} with real part {2} and imaginary part {3}; the imaginary unit satisfies {4}.",
