"Ziehe die {0} in der Gauss-Ebene: Ihr {1} ist die Koordinate nach rechts, ihr {2} die Koordinate nach oben. Der {3} ist die Länge des Zeigers, das {4} sein Winkel zur positiven reellen Achse. Die {5} liegt gespiegelt an der reellen Achse.": "Drag the {0} in the complex plane: its {1} is the coordinate to the right, its {2} the coordinate upwards. The {3} is the length of the arrow, the {4} its angle to the positive real axis. The {5} is the mirror image in the real axis.",
"{0} Ziehe die farbigen Punkte in der Gauss-Ebene: Zeiger, Winkel und Rechenweg rechnen mit. Links wählst du die Ansicht.": "{0} Drag the coloured points in the complex plane: arrows, angles and the worked solution follow. Choose the view on the left.",
"liegt auf der imaginären Achse": "lies on the imaginary axis",
"Für {0} ist kein Winkel festgelegt.": "For {0} no angle is defined.",
"Mit diesen Werten lässt sich kein Bild zeichnen.": "No picture can be drawn with these values.",
"Eine komplexe Zahl z = a + bi besteht aus zwei reellen Zahlen: dem Realteil a und dem Imaginärteil b. Die imaginäre Einheit i erfüllt i² = −{0}. Man zeichnet z als Punkt (a | b) oder als Zeiger vom Ursprung aus. Die Polarform beschreibt denselben Punkt durch Betrag und Winkel.": "A complex number z = a + bi consists of two real numbers: the real part a and the imaginary part b. The imaginary unit i satisfies i² = −{0}. z is drawn as the point (a | b) or as an arrow from the origin. The polar form describes the same point by modulus and angle.",
"Gauss-Ebene mit Betrag und Argument, Addieren und Subtrahieren als Zeiger, Multiplizieren und Dividieren als Drehstreckung, Potenzen (Moivre), Wurzeln und Einheitswurzeln, quadratische Gleichungen mit komplexen Lösungen": "Complex plane with modulus and argument, adding and subtracting as arrows, multiplying and dividing as rotation and scaling, powers (de Moivre), roots and roots of unity, quadratic equations with complex solutions",
"Komplexe Zahlen": "Complex numbers",
"ℂ Komplexe Zahlen": "ℂ Complex numbers",
