"Quadratische Gleichungen": "Quadratic equations",
"Wurzeln und Einheitswurzeln": "Roots and roots of unity",
"Potenzen (Formel von Moivre)": "Powers (de Moivre's formula)",
"Multiplizieren und Dividieren": "Multiplying and dividing",
"Addieren und Subtrahieren": "Adding and subtracting",
"Zahl in der Gauss-Ebene": "Number in the complex plane",
"Ist die Diskriminante negativ, zieht man die Wurzel mit Hilfe der imaginären Einheit. Jede quadratische Gleichung mit reellen Koeffizienten hat damit zwei Lösungen (oder eine doppelte). Die Sätze von Vieta für Summe und Produkt der Lösungen gelten weiter.": "If the discriminant is negative, the square root is taken with the help of the imaginary unit. Every quadratic equation with real coefficients then has two solutions (or one double solution). Vieta's formulas for the sum and product of the solutions still hold.",
"Aus der Formel von Moivre folgt: Alle n-ten Wurzeln von w haben denselben Betrag, und ihre Winkel unterscheiden sich um den n-ten Teil des Vollwinkels. Für w = {0} heissen sie Einheitswurzeln.": "De Moivre's formula implies: all n-th roots of w have the same modulus, and their angles differ by one n-th of a full turn. For w = {0} they are called roots of unity.",
"Formel von Moivre: Die n-te Potenz hat den n-fachen Winkel, und ihr Betrag ist die n-te Potenz des Betrags. Ist der Betrag grösser als {0}, laufen die Potenzen auf einer Spirale nach aussen, ist er kleiner als {1}, nach innen.": "De Moivre's formula: the n-th power has n times the angle, and its modulus is the n-th power of the modulus. If the modulus is greater than {0}, the powers run outwards on a spiral; if it is less than {1}, inwards.",
"Gerechnet wird wie mit Klammern, mit i² = −{0}. In der Polarform ist das Produkt eine Drehstreckung: Beträge multiplizieren, Winkel addieren. Beim Dividieren ist es umgekehrt: Beträge dividieren, Winkel subtrahieren; in der Normalform erweitert man mit der konjugierten Zahl des Nenners.": "You calculate as with brackets, using i² = −{0}. In polar form the product is a rotation with scaling: multiply the moduli, add the angles. Dividing works the other way round: divide the moduli, subtract the angles; in algebraic form you expand the fraction with the conjugate of the denominator.",
"Komplexe Zahlen addiert und subtrahiert man getrennt nach Realteil und Imaginärteil, genau wie Vektoren in der Ebene. Der Betrag der Differenz ist der Abstand der beiden Punkte.": "Complex numbers are added and subtracted separately by real and imaginary part, just like vectors in the plane. The modulus of the difference is the distance between the two points.",
"Bei «Wurzeln» kannst du jede Lösung ziehen: Die Zahl w wird dann als n-te Potenz dieser Lösung neu berechnet.": "In “Roots” you can drag any solution: the number w is then recalculated as the n-th power of that solution.",
"Die Punkte rasten beim Ziehen auf runden Werten ein; genaue Werte tippst du links in die Felder.": "While dragging, the points snap to round values; exact values can be typed into the fields on the left.",
"Die Beträge darf man nicht einfach addieren: {0} (Dreiecksungleichung). Hier: {1}.": "The moduli must not simply be added: {0} (triangle inequality). Here: {1}.",
"<0>Im Bild:</0> Der Zeiger {1} wird an die Spitze von {2} gehängt. Die Summe ist die Diagonale des Parallelogramms mit den Seiten {3} und {4}.": "<0>In the picture:</0> The arrow {1} is attached to the tip of {2}. The sum is the diagonal of the parallelogram with sides {3} and {4}.",
"<0>Getrennt rechnen:</0> Realteile und Imaginärteile werden je für sich addiert.": "<0>Calculate separately:</0> Real parts and imaginary parts are each added on their own.",
"<0>Getrennt rechnen:</0> Realteile und Imaginärteile werden je für sich subtrahiert.": "<0>Calculate separately:</0> Real parts and imaginary parts are each subtracted on their own.",
