"Ziehe {0} und {1}: Die {2} entsteht, indem man den zweiten Zeiger an die Spitze des ersten hängt ({3}). Beim Subtrahieren wird die Gegenzahl −z₂ angehängt.": "Drag {0} and {1}: the {2} is obtained by attaching the second arrow to the tip of the first ({3}). For subtraction, the opposite −z₂ is attached.",
"<0>Abstand:</0> Die Differenz ist der Zeiger von {1} nach {2}; ihr Betrag ist der Abstand der beiden Punkte.": "<0>Distance:</0> The difference is the arrow from {1} to {2}; its modulus is the distance between the two points.",
"<0>Im Bild:</0> Subtrahieren heisst, die Gegenzahl {1} zu addieren. Der Zeiger {2} wird an die Spitze von {3} gehängt.": "<0>In the picture:</0> Subtracting means adding the opposite {1}. The arrow {2} is attached to the tip of {3}.",
"<0>Im Bild:</0> Multiplizieren mit {1} dreht den Zeiger {2} um {3} und streckt ihn mit dem Faktor {4} (Drehstreckung). Das Dreieck {5} ist ähnlich zum Dreieck {6}.": "<0>In the picture:</0> Multiplying by {1} rotates the arrow {2} by {3} and stretches it by the factor {4} (rotation with scaling). The triangle {5} is similar to the triangle {6}.",
"<0>Polarform:</0> Beträge multiplizieren, Winkel addieren.": "<0>Polar form:</0> Multiply the moduli, add the angles.",
"<0>Polarform:</0> Beträge dividieren, Winkel subtrahieren.": "<0>Polar form:</0> Divide the moduli, subtract the angles.",
"<0>Ausmultiplizieren:</0> Jeder Summand wird mit jedem multipliziert, dann setzt man {1} ein.": "<0>Expand:</0> Each term is multiplied by each term, then {1} is substituted.",
"{0} Drehen und strecken": "{0} Rotate and stretch",
