"Produkt": "product",
"Ziehe {0} und {1}: Beim {2} werden die Beträge multipliziert und die {3}. Die beiden {4} sind ähnlich, denn Multiplizieren mit z₂ dreht um den Winkel von z₂ und streckt mit dessen Betrag. «{5} Drehen und strecken» zeigt die Bewegung.": "Drag {0} and {1}: for the {2} the moduli are multiplied and the {3}. The two {4} are similar, because multiplying by z₂ rotates by the angle of z₂ and stretches by its modulus. “{5} Rotate and stretch” shows the motion.",
"Winkel ab {0} werden um {1} verkleinert: {2}.": "Angles from {0} upwards are reduced by {1}: {2}.",
"Negative Winkel werden um {0} vergrössert: {1}.": "Negative angles are increased by {0}: {1}.",
"<0>Im Bild:</0> Dividieren durch {1} dreht den Zeiger {2} um {3} zurück und staucht ihn mit dem Faktor {4}. Das Dreieck {5} ist ähnlich zum Dreieck {6}.": "<0>In the picture:</0> Dividing by {1} rotates the arrow {2} back by {3} and shrinks it by the factor {4}. The triangle {5} is similar to the triangle {6}.",
"<0>Mit der konjugierten Zahl erweitern:</0> So wird der Nenner reell, denn {1}.": "<0>Expand with the conjugate:</0> This makes the denominator real, because {1}.",
"Durch {0} kann man nicht dividieren. Wähle {1}.": "You cannot divide by {0}. Choose {1}.",
"Wegen {0} wachsen die Beträge: Die Potenzen laufen auf einer Spirale nach aussen.": "Since {0}, the moduli grow: the powers run outwards on a spiral.",
"Wegen {0} schrumpfen die Beträge: Die Potenzen laufen auf einer Spirale nach innen.": "Since {0}, the moduli shrink: the powers run inwards on a spiral.",
"Wegen {0} bleiben alle Potenzen auf dem Einheitskreis.": "Since {0}, all powers stay on the unit circle.",
"<0>Schritt für Schritt:</0> Jede Multiplikation mit {1} dreht um {2} weiter und streckt mit dem Faktor {3}.": "<0>Step by step:</0> Each multiplication by {1} rotates further by {2} and stretches by the factor {3}.",
"<0>Formel von Moivre:</0> Beim Potenzieren wird der Betrag potenziert und der Winkel vervielfacht.": "<0>De Moivre's formula:</0> When raising to a power, the modulus is raised to that power and the angle is multiplied.",
