"Ziehe {0} und wähle den Exponenten: Jede {1} dreht um den {2} weiter und streckt mit demselben Faktor. Liegt z auf dem {3}, bleiben alle Potenzen darauf.": "Drag {0} and choose the exponent: each {1} rotates further by the {2} and stretches by the same factor. If z lies on the {3}, all powers stay on it.",
"Die Gleichung {0} hat {1} Lösungen mit dem Betrag {2}": "The equation {0} has {1} solutions with modulus {2}",
"<0>Im Bild:</0> Die Lösungen liegen auf einem Kreis um {1} und teilen ihn in {2} gleiche Teile. Benachbarte Lösungen schliessen den Winkel {3} ein.": "<0>In the picture:</0> The solutions lie on a circle around {1} and divide it into {2} equal parts. Neighbouring solutions enclose the angle {3}.",
"<0>Ansatz in Polarform:</0> Aus {1} folgt für die Beträge {2} und für die Winkel {3}.": "<0>Approach in polar form:</0> From {1} it follows for the moduli that {2} and for the angles that {3}.",
"Grad n der Wurzel": "Degree n of the root",
"Einheitswurzeln: z⁶ = {0}": "Roots of unity: z⁶ = {0}",
"Einheitswurzeln: z⁵ = {0}": "Roots of unity: z⁵ = {0}",
