"Stelle {0} und Zuwachs pro Zeitschritt ein: Die {1} sind alle gleich hoch, die {2} liegen auf einer {3}. Ziehe den {4}, um den Bestand zu einem beliebigen Zeitpunkt abzulesen.": "Set the {0} and the increase per time step: the {1} are all equally high, the {2} lie on a {3}. Drag the {4} to read off the quantity at any time.",
"Stelle {0} und Prozentsatz ein: Jede der {1} ist um denselben Faktor höher als die vorige, die {2} wird immer steiler. Die {3} ist überall gleich lang. Ziehe den {4}.": "Set the {0} and the percentage: each of the {1} is higher than the previous one by the same factor, and the {2} gets steeper and steeper. The {3} is the same everywhere. Drag the {4}.",
"Stelle {0}, {1} und Anteil k ein: Jede der {2} schliesst denselben Anteil der Lücke bis zur Schranke. Die {3} wird immer flacher und kommt der Schranke beliebig nahe. Ziehe den {4}.": "Set the {0}, the {1} and the share k: each of the {2} closes the same share of the gap to the limit. The {3} gets flatter and flatter and comes arbitrarily close to the limit. Drag the {4}.",
"Stelle {0}, {1} und Wachstumskonstante ein: Die {2} wächst zuerst fast exponentiell, am {3} bei halber Schranke am schnellsten und nähert sich dann der Schranke. Ziehe den {4}.": "Set the {0}, the {1} and the growth constant: the {2} first grows almost exponentially, grows fastest at the {3} at half the limit and then approaches the limit. Drag the {4}.",
"Alle Modelle starten beim selben {0}: {1} und {2}. Verstelle die Regler, bis ein Modell die {3} trifft; die {4} zeigt, welches am besten passt.": "All models start from the same {0}: {1} and {2}. Adjust the sliders until one model hits the {3}; the {4} shows which one fits best.",
