"Trage links die {0} und die {1} ein: Jede Zahlung wird mit dem Kalkulationszinssatz zu ihrem {2} abgezinst. Die Summe aller Barwerte ist der {3}; ist er positiv, lohnt sich die Investition.": "Enter the {0} and the {1} on the left: each payment is discounted at the discount rate to its {2}. The sum of all present values is the {3}; if it is positive, the investment pays off.",
"Ziehe den {0} entlang der {1}: Je höher der Zinssatz, desto kleiner der Kapitalwert. Beim {2} ist der Kapitalwert genau null; liegt er über dem Kalkulationszinssatz, lohnt sich die Investition.": "Drag the {0} along the {1}: the higher the rate, the smaller the net present value. At the {2} the net present value is exactly zero; if it lies above the discount rate, the investment pays off.",
"Die {0} summiert die Zahlungen ohne Zins, die {1} die abgezinsten Zahlungen. Wo eine Linie die Nulllinie kreuzt, ist die Investition zurückgeflossen: nach der {2} und nach der {3}.": "The {0} adds up the payments without interest, the {1} the discounted payments. Where a line crosses the zero line, the investment has been recovered: after the {2} and after the {3}.",
"Vergleiche {0} und {1}: Ziehe den {2} und lies ab, welche den grösseren Kapitalwert hat. Am {3} sind beide gleich gut; links und rechts davon ist jeweils eine andere besser.": "Compare {0} and {1}: drag the {2} and read off which one has the larger net present value. At the {3} both are equally good; to the left and to the right of it a different one is better.",
