"Kapitalwert {0}: Die Investition bringt genau die verlangte Verzinsung": "Net present value {0}: the investment yields exactly the required rate",
"<0>Annuität:</0> der Kapitalwert, umgerechnet in einen gleich hohen Betrag am Ende jedes Jahres.": "<0>Annuity:</0> the net present value, converted into an equal amount at the end of each year.",
"<0>Entscheid:</0> Ein positiver Kapitalwert heisst, dass die Investition mehr einbringt als eine Anlage zum Kalkulationszinssatz.": "<0>Decision:</0> a positive net present value means that the investment yields more than an investment at the discount rate.",
"<0>Kapitalwert:</0> die Summe aller Barwerte, vermindert um die Investition.": "<0>Net present value:</0> the sum of all present values, reduced by the investment.",
"<0>Abzinsen:</0> Geld, das erst in {1} Jahren fliesst, ist heute weniger wert. Jede Zahlung wird darum durch {2} geteilt, mit dem Zinsfaktor {3}.": "<0>Discounting:</0> money that only flows in {1} years is worth less today. Each payment is therefore divided by {2}, with the interest factor {3}.",
"Interner Zinssatz {0}: Die Investition lohnt sich nicht bei einem Kalkulationszinssatz von {1}": "Internal rate of return {0}: the investment does not pay off at a discount rate of {1}",
"Interner Zinssatz {0}: Die Investition lohnt sich bei einem Kalkulationszinssatz von {1}": "Internal rate of return {0}: the investment pays off at a discount rate of {1}",
"<0>Entscheid:</0> Liegt der interne Zinssatz über dem Kalkulationszinssatz, lohnt sich die Investition.": "<0>Decision:</0> if the internal rate of return lies above the discount rate, the investment pays off.",
"Genauer Wert (mit weiteren Schritten): {0}.": "More precise value (with further steps): {0}.",
"<0>Linear interpolieren:</0> Zwischen den beiden Punkten wird die Kurve durch eine Gerade ersetzt.": "<0>Linear interpolation:</0> between the two points the curve is replaced by a straight line.",
"<0>Probieren:</0> Die Gleichung lässt sich meist nicht nach {1} auflösen. Man sucht zwei Zinssätze, zwischen denen der Kapitalwert das Vorzeichen wechselt.": "<0>Trial:</0> the equation usually cannot be solved for {1}. One looks for two rates between which the net present value changes sign.",
"<0>Interner Zinssatz:</0> der Zinssatz, bei dem der Kapitalwert genau {1} ist. Er gibt an, zu wie viel Prozent sich das eingesetzte Kapital verzinst.": "<0>Internal rate of return:</0> the rate at which the net present value is exactly {1}. It tells at what percentage the capital employed earns interest.",
"Der Kapitalwert ist bei jedem Zinssatz negativ": "The net present value is negative at every rate",
"Der Kapitalwert ist bei jedem Zinssatz positiv": "The net present value is positive at every rate",
"Der Kapitalwert ist bei jedem Zinssatz null": "The net present value is zero at every rate",
"Zwischen {0} und {1} wechselt der Kapitalwert sein Vorzeichen nicht: Es gibt dort keinen internen Zinssatz.": "Between {0} and {1} the net present value does not change sign: there is no internal rate of return there.",
"Amortisationszeit: statisch {0} Jahre, dynamisch {1} Jahre": "Payback period: static {0} years, dynamic {1} years",
"Amortisationszeit: statisch {0} Jahre, dynamisch nie": "Payback period: static {0} years, dynamic never",
"Amortisationszeit: statisch nie, dynamisch nie": "Payback period: static never, dynamic never",
"Die Amortisationszeit misst das Risiko, nicht den Gewinn: Zahlungen nach diesem Zeitpunkt werden nicht beachtet.": "The payback period measures the risk, not the profit: payments after this time are ignored.",
"<0>Dynamisch:</0> Dasselbe mit den abgezinsten Zahlungen. Spätere Rückflüsse zählen weniger, darum dauert die Amortisation länger.": "<0>Dynamic:</0> the same with the discounted payments. Later returns count less, so payback takes longer.",
"Im Jahr des Vorzeichenwechsels wird ein gleichmässiger Zufluss angenommen:": "In the year of the sign change an even inflow is assumed:",
"<0>Statisch:</0> Die Zahlungen werden ohne Zins aufsummiert, bis die Investition zurückgeflossen ist.": "<0>Static:</0> the payments are added up without interest until the investment has been recovered.",
"Mit Zins gerechnet fliesst die Investition in der Laufzeit nicht zurück.": "Calculated with interest, the investment is not recovered within its lifetime.",
"Die Rückflüsse decken die Investition nicht.": "The returns do not cover the investment.",
"Bei {0} ist Investition A besser": "At {0} investment A is better",
"Bei {0} ist Investition B besser": "At {0} investment B is better",
"Bei {0} lohnt sich keine der beiden Investitionen": "At {0} neither of the two investments pays off",
"Bei {0} sind beide Investitionen gleich gut": "At {0} both investments are equally good",
"<0>Entscheid:</0> Gewählt wird die Investition mit dem grösseren Kapitalwert, sofern er positiv ist.": "<0>Decision:</0> the investment with the larger net present value is chosen, provided it is positive.",
"Kapitalwert und interner Zinssatz führen hier zu verschiedenen Rangfolgen. Massgebend ist der Kapitalwert beim eigenen Kalkulationszinssatz.": "Here net present value and internal rate of return lead to different rankings. What counts is the net present value at your own discount rate.",
"<0>Gleichstand:</0> Bei diesem Zinssatz haben beide Investitionen denselben Kapitalwert. Darunter ist die eine besser, darüber die andere.": "<0>Break-even rate:</0> at this rate both investments have the same net present value. Below it one is better, above it the other.",
