"Verknüpfungen (nicht, und, oder, entweder–oder, wenn–dann, genau dann wenn) mit Wahrheitstafel und Mengenbild, Wahrheitstafel beliebiger Aussagen, Tautologie und Widerspruch, gleichwertige Aussagen und Gesetze, Implikation mit Umkehrung und Kontraposition": "Connectives (not, and, or, either–or, if–then, if and only if) with truth table and Venn diagram, truth table of any statement, tautology and contradiction, equivalent statements and laws, implication with converse and contrapositive",
"Aussagen verknüpfen und auswerten: Wahrheitstafeln Schritt für Schritt, das passende Mengenbild dazu, die wichtigsten Gesetze zum Umformen und der Unterschied zwischen einer Implikation und ihrer Umkehrung.": "Combining and evaluating statements: truth tables step by step, the matching Venn diagram, the most important laws for transforming statements, and the difference between an implication and its converse.",
"{0} Klicke eine Zeile der Wahrheitstafel an oder tippe links eine eigene Aussage ein. Das Mengenbild zeigt, wo sie wahr ist.": "{0} Click a row of the truth table or type your own statement on the left. The Venn diagram shows where it is true.",
"Aussagen tippst du mit den Knöpfen unter dem Feld oder über die Tastatur: ! für nicht, & für und, | für oder, ^ für entweder–oder; die Pfeile als Minus- und Grösser-Zeichen. Auch die Wörter nicht, und, oder werden verstanden.": "Type statements with the buttons below the field or with the keyboard: ! for not, & for and, | for or, ^ for either–or; the arrows as minus and greater-than signs. The words not, and, or are understood as well.",
"Ohne Klammern gilt: zuerst nicht, dann und, dann oder, dann wenn–dann, zuletzt genau dann wenn. Erlaubt sind bis zu vier Variablen; ein Mengenbild gibt es bei zwei oder drei.": "Without brackets the order is: first not, then and, then or, then if–then, finally if and only if. Up to four variables are allowed; a Venn diagram is shown for two or three.",
"Die Wahrheitswerte stehen als w und f oder als {0} und {1}; die Wahl gilt für alle Ansichten.": "The truth values are shown as w and f (true, false) or as {0} and {1}; the choice applies to all views.",
"Eine Aussage ist entweder wahr oder falsch. Verknüpfungen bilden aus Aussagen neue Aussagen; die Wahrheitstafel legt für jede Kombination der Wahrheitswerte fest, ob die neue Aussage wahr ist. Im Mengenbild bedeutet «im Kreis A»: A ist wahr.": "A statement is either true or false. Connectives form new statements from statements; the truth table fixes, for every combination of truth values, whether the new statement is true. In the Venn diagram, “inside circle A” means: A is true.",
"Bei n Variablen hat die Wahrheitstafel {0}ⁿ Zeilen. Man rechnet von innen nach aussen: zuerst Klammern und Verneinungen, dann «und», dann «oder», zuletzt die Pfeile. Eine Tautologie ist immer wahr, ein Widerspruch immer falsch.": "With n variables the truth table has {0}ⁿ rows. You calculate from the inside out: first brackets and negations, then “and”, then “or”, finally the arrows. A tautology is always true, a contradiction always false.",
"Zwei Aussagen sind gleichwertig (äquivalent), wenn sie bei jeder Belegung denselben Wahrheitswert haben. Wichtige Gesetze: De Morgan, Distributivgesetze, doppelte Verneinung, Kontraposition. Mit ihnen formt man Aussagen um wie Terme in der Algebra.": "Two statements are equivalent if they have the same truth value for every assignment. Important laws: De Morgan, distributive laws, double negation, contraposition. With them, statements are transformed like terms in algebra.",
"Aus «wenn A, dann B» folgt nicht «wenn B, dann A». Gleichwertig ist nur die Kontraposition «wenn nicht B, dann nicht A»; darauf beruht der indirekte Beweis. A heisst hinreichend für B, B notwendig für A.": "From “if A, then B” it does not follow that “if B, then A”. Only the contrapositive “if not B, then not A” is equivalent; indirect proof is based on it. A is called sufficient for B, B necessary for A.",
"logische Verknüpfung": "logical connective",
