"letzten Spalte": "last column",
"blaue": "blue",
"grüne Aussage": "green statement",
"Belegung": "assignment of truth values",
"Implikation A → B": "implication A → B",
"Kontraposition ¬B → ¬A": "contrapositive ¬B → ¬A",
"Umkehrung B → A": "converse B → A",
"Verneinung A ∧ ¬B": "negation A ∧ ¬B",
"Wähle links eine {0} und klicke eine Zeile der {1} an: Die {2} gehört zu einem Feld im {3}. Schraffiert sind die Felder, in denen die verknüpfte Aussage wahr ist.": "Choose a {0} on the left and click a row of the {1}: the {2} belongs to a region in the {3}. The hatched regions are those in which the combined statement is true.",
"Tippe links eine {0} ein: Die {1} rechnet sie für alle Belegungen aus, von den {2} bis zur {3}. Steht dort überall «wahr», ist die Aussage eine Tautologie.": "Type a {0} on the left: the {1} evaluates it for all assignments, from the {2} to the {3}. If it says “true” everywhere there, the statement is a tautology.",
"Vergleiche die {0} und die {1}: Stimmen ihre Spalten in der {2} überall überein, sind sie gleichwertig; dann sind auch die {3} gleich schraffiert. Unter «Beispiel wählen …» stehen die wichtigsten Gesetze.": "Compare the {0} and the {1}: if their columns in the {2} agree everywhere, they are equivalent; then the {3} are hatched in the same way. The most important laws are listed under “Choose an example …”.",
"Wähle ein Beispiel und klicke eine {0} an: Die {1} ist nur falsch, wenn A wahr und B falsch ist. Die {2} hat dieselben Wahrheitswerte und ist gleichwertig, die {3} nicht. Die {4} ist genau dann wahr, wenn die Implikation falsch ist.": "Choose an example and click an {0}: the {1} is only false when A is true and B is false. The {2} has the same truth values and is equivalent, the {3} is not. The {4} is true exactly when the implication is false.",
"Verknüpfung": "Connective",
"Negation (nicht)": "Negation (not)",
"Konjunktion (und)": "Conjunction (and)",
"Disjunktion (oder)": "Disjunction (or)",
"Entweder – oder": "Either – or",
"Implikation (wenn – dann)": "Implication (if – then)",
"Äquivalenz (genau dann, wenn)": "Equivalence (if and only if)",
