"Belegung anklicken": "Click a column",
"Aktuelle Zeile: {0} ist wahr": "Current row: {0} is true",
"Aktuelle Zeile: {0} ist falsch": "Current row: {0} is false",
"<0>Mengenbild:</0> Im Kreis A ist die Aussage A wahr, ausserhalb ist sie falsch. Schraffiert sind die Felder, in denen die verknüpfte Aussage wahr ist.": "<0>Venn diagram:</0> Inside circle A the statement A is true, outside it is false. The hatched regions are those in which the combined statement is true.",
"<0>Negation (nicht):</0> Die Negation kehrt den Wahrheitswert um: Aus wahr wird falsch, aus falsch wird wahr.": "<0>Negation (not):</0> The negation reverses the truth value: true becomes false, false becomes true.",
"Gelesen «nicht A». Beispiel: A «Es regnet.» wird zu «Es regnet nicht.»": "Read “not A”. Example: A “It is raining.” becomes “It is not raining.”",
"<0>Konjunktion (und):</0> Die Konjunktion ist nur wahr, wenn beide Aussagen wahr sind.": "<0>Conjunction (and):</0> The conjunction is only true when both statements are true.",
"Gelesen «A und B». Beispiel: «Es regnet, und es ist kalt.»": "Read “A and B”. Example: “It is raining, and it is cold.”",
"<0>Disjunktion (oder):</0> Die Disjunktion ist wahr, wenn mindestens eine der beiden Aussagen wahr ist. Auch beide dürfen wahr sein (einschliessendes Oder).": "<0>Disjunction (or):</0> The disjunction is true when at least one of the two statements is true. Both may be true as well (inclusive or).",
"Gelesen «A oder B». Beispiel: «Zum Kaffee nehme ich Milch oder Zucker» schliesst beides zusammen nicht aus.": "Read “A or B”. Example: “I take milk or sugar with my coffee” does not rule out both together.",
"<0>Entweder – oder:</0> Das ausschliessende Oder ist wahr, wenn genau eine der beiden Aussagen wahr ist.": "<0>Either – or:</0> The exclusive or is true when exactly one of the two statements is true.",
"Gelesen «entweder A oder B». Beispiel: «Ich fahre entweder mit dem Zug oder mit dem Auto.»": "Read “either A or B”. Example: “I go either by train or by car.”",
"<0>Implikation (wenn – dann):</0> Die Implikation ist nur falsch, wenn A wahr und B falsch ist. Ist A falsch, gilt sie als wahr.": "<0>Implication (if – then):</0> The implication is only false when A is true and B is false. If A is false, it counts as true.",
"Gelesen «wenn A, dann B». Beispiel: «Wenn es regnet, ist die Strasse nass.» Bei trockenem Wetter ist dieses Versprechen nicht gebrochen.": "Read “if A, then B”. Example: “If it rains, the road is wet.” In dry weather this promise is not broken.",
"<0>Äquivalenz (genau dann, wenn):</0> Die Äquivalenz ist wahr, wenn beide Aussagen denselben Wahrheitswert haben.": "<0>Equivalence (if and only if):</0> The equivalence is true when both statements have the same truth value.",
"Gelesen «A genau dann, wenn B». Beispiel: «Eine Zahl ist genau dann gerade, wenn ihre letzte Ziffer gerade ist.»": "Read “A if and only if B”. Example: “A number is even if and only if its last digit is even.”",
"Zeilen": "Rows",
"<0>Belegungen:</0> Bei {1} Variablen gibt es {2} Zeilen, weil jede Variable wahr oder falsch sein kann.": "<0>Assignments:</0> With {1} variables there are {2} rows, because each variable can be true or false.",
"<0>Reihenfolge:</0> Man rechnet von innen nach aussen, jede Teilaussage in einer eigenen Spalte.": "<0>Order:</0> You calculate from the inside out, each partial statement in its own column.",
"<0>Auswertung:</0> Die letzte Spalte zeigt, für welche Belegungen die Aussage wahr ist.": "<0>Evaluation:</0> The last column shows for which assignments the statement is true.",
"Die Aussage ist in {0} von {1} Zeilen wahr: erfüllbar, aber keine Tautologie": "The statement is true in {0} of {1} rows: satisfiable, but not a tautology",
"Die Aussage ist in allen {0} Zeilen wahr: eine Tautologie": "The statement is true in all {0} rows: a tautology",
"Die Aussage ist in keiner Zeile wahr: ein Widerspruch": "The statement is true in no row: a contradiction",
"Tautologie: in jeder Zeile wahr": "Tautology: true in every row",
"Widerspruch: in keiner Zeile wahr": "Contradiction: true in no row",
"Erfüllbar, aber nicht immer wahr": "Satisfiable, but not always true",
"Tautologie: A ∨ ¬A": "Tautology: A ∨ ¬A",
"Widerspruch: A ∧ ¬A": "Contradiction: A ∧ ¬A",
"Drei Variablen: (A ∧ B) ∨ C": "Three variables: (A ∧ B) ∨ C",
"Immer wahr: A → (B → A)": "Always true: A → (B → A)",
"Modus tollens: (A → B) ∧ ¬B": "Modus tollens: (A → B) ∧ ¬B",
"Kettenschluss": "Chain rule (hypothetical syllogism)",
"Entweder – oder mit ∧ und ∨": "Either – or with ∧ and ∨",
"Gleichwertige Aussagen": "Equivalent statements",
"Erste Aussage (blau)": "First statement (blue)",
"Zweite Aussage (grün)": "Second statement (green)",
"<0>Gleichwertig</0> heissen zwei Aussagen, wenn sie bei jeder Belegung denselben Wahrheitswert haben. Man vergleicht ihre Spalten in der Wahrheitstafel Zeile für Zeile.": "Two statements are called <0>equivalent</0> if they have the same truth value for every assignment. Their columns in the truth table are compared row by row.",
"<0>Vergleich:</0> In allen {1} Zeilen stimmen die beiden Spalten überein. Im Mengenbild sind dieselben Felder schraffiert.": "<0>Comparison:</0> In all {1} rows the two columns agree. In the Venn diagram the same regions are hatched.",
"<0>Unterschied:</0> Bei diesen Belegungen haben die beiden Aussagen verschiedene Wahrheitswerte.": "<0>Difference:</0> For these assignments the two statements have different truth values.",
"Gleichwertige Aussagen darf man gegeneinander austauschen, so wie man in der Algebra Terme umformt.": "Equivalent statements may be exchanged for one another, just as terms are transformed in algebra.",
"Die Aussagen sind gleichwertig": "The statements are equivalent",
"Die Aussagen sind nicht gleichwertig: Unterschied in {0} von {1} Zeilen": "The statements are not equivalent: they differ in {0} of {1} rows",
"Gleichwertig: beide Spalten stimmen überein": "Equivalent: both columns agree",
"Nicht gleichwertig: rote Zeilen unterscheiden sich": "Not equivalent: the red rows differ",
"De Morgan: ¬(A ∧ B) und ¬A ∨ ¬B": "De Morgan: ¬(A ∧ B) and ¬A ∨ ¬B",
"De Morgan: ¬(A ∨ B) und ¬A ∧ ¬B": "De Morgan: ¬(A ∨ B) and ¬A ∧ ¬B",
"Implikation ohne Pfeil: ¬A ∨ B": "Implication without arrow: ¬A ∨ B",
"Kontraposition": "Contrapositive",
"Umkehrung: nicht gleichwertig": "Converse: not equivalent",
