"Wenn eine Zahl durch {0} teilbar ist, ist sie gerade.": "If a number is divisible by {0}, it is even.",
"Wenn eine Zahl gerade ist, ist sie durch {0} teilbar.": "If a number is even, it is divisible by {0}.",
