"Ziehe die Spitzen der Vektoren {0} und {1}: Hängt man den zweiten Pfeil an die Spitze des ersten, zeigt der {2} vom Anfang zum Ende. Das {3} zeigt, dass die Reihenfolge keine Rolle spielt. Wähle links Summe, Differenz oder Linearkombination.": "Drag the tips of the vectors {0} and {1}: if the second arrow is attached to the tip of the first, the {2} points from the start to the end. The {3} shows that the order does not matter. Choose sum, difference or linear combination on the left.",
