"Die {0} ist durch den {1} und den {2} festgelegt. Ziehe den {3} oder stelle links den Parameter t ein: Bei t = {4} liegt P an der Spitze von v, bei t = {5} doppelt so weit. Der {6} steht senkrecht auf der Geraden und liefert die Koordinatengleichung.": "The {0} is fixed by the {1} and the {2}. Drag the {3} or set the parameter t on the left: for t = {4}, P lies at the tip of v, for t = {5} twice as far. The {6} is perpendicular to the line and yields the coordinate equation.",
