"<0>Komponenten:</0> Koordinaten des Endpunkts minus Koordinaten des Anfangspunkts.": "<0>Components:</0> coordinates of the end point minus coordinates of the start point.",
"<0>Betrag (Länge):</0> Satz des Pythagoras im Dreieck aus den beiden Komponenten.": "<0>Magnitude (length):</0> Pythagoras' theorem in the triangle formed by the two components.",
"<0>Richtungswinkel:</0> Winkel zwischen der positiven x-Richtung und dem Vektor, im Gegenuhrzeigersinn gemessen.": "<0>Direction angle:</0> angle between the positive x-direction and the vector, measured anticlockwise.",
"Der Vektor zeigt nach links: Zum Wert des Taschenrechners kommen {0} dazu.": "The vector points to the left: {0} is added to the calculator's value.",
"<0>Einheitsvektor:</0> Der Vektor wird durch seinen Betrag geteilt; so bleibt die Richtung, und die Länge wird {1}.": "<0>Unit vector:</0> the vector is divided by its magnitude; the direction stays and the length becomes {1}.",
"<0>Gegenvektor:</0> gleiche Länge, entgegengesetzte Richtung.": "<0>Opposite vector:</0> same length, opposite direction.",
"{0} mit dem Betrag {1}": "{0} with magnitude {1}",
"A und B fallen zusammen: Das ist der Nullvektor. Er hat die Länge {0} und keine Richtung.": "A and B coincide: this is the zero vector. It has length {0} and no direction.",
"{0} ist der Nullvektor": "{0} is the zero vector",
"<0>Summe:</0> Die Komponenten werden einzeln addiert. Im Bild wird {1} an die Spitze von {2} gehängt.": "<0>Sum:</0> the components are added one by one. In the picture {1} is attached to the tip of {2}.",
"Die Reihenfolge spielt keine Rolle: {0}. Beide Wege führen im Parallelogramm zur selben Ecke.": "The order does not matter: {0}. Both paths lead to the same corner of the parallelogram.",
"<0>Differenz:</0> Die Komponenten werden einzeln subtrahiert. Das ist dasselbe wie die Summe mit dem Gegenvektor {1}.": "<0>Difference:</0> the components are subtracted one by one. This is the same as the sum with the opposite vector {1}.",
"{0} führt von der Spitze von {1} zur Spitze von {2}.": "{0} leads from the tip of {1} to the tip of {2}.",
"<0>Vielfache:</0> Jede Komponente wird mit der Zahl multipliziert.": "<0>Multiples:</0> each component is multiplied by the number.",
"<0>Linearkombination:</0> Die beiden Vielfachen werden addiert.": "<0>Linear combination:</0> the two multiples are added.",
"{0} und {1} sind parallel: Alle Linearkombinationen liegen auf einer Geraden.": "{0} and {1} are parallel: all linear combinations lie on one line.",
"{0} und {1} sind nicht parallel: Mit passenden Faktoren lässt sich jeder Vektor der Ebene erreichen.": "{0} and {1} are not parallel: with suitable factors every vector of the plane can be reached.",
"Betrag des Ergebnisses:": "Magnitude of the result:",
"<0>Skalarprodukt:</0> Die Komponenten werden paarweise multipliziert und die Produkte addiert. Das Ergebnis ist eine Zahl.": "<0>Scalar product:</0> the components are multiplied in pairs and the products added. The result is a number.",
"Einer der Vektoren ist der Nullvektor: Ein Winkel lässt sich nicht angeben.": "One of the vectors is the zero vector: an angle cannot be given.",
"Beträge:": "Magnitudes:",
"<0>Winkel:</0> Das Skalarprodukt ist auch {1}. Auflösen nach {2}:": "<0>Angle:</0> the scalar product is also {1}. Solving for {2}:",
"Das Skalarprodukt ist null: Die beiden Vektoren stehen senkrecht aufeinander.": "The scalar product is zero: the two vectors are perpendicular to each other.",
"<0>Projektion von b auf a:</0> Länge des Schattens von {1} in Richtung von {2} (negativ, wenn er in die Gegenrichtung zeigt).": "<0>Projection of b onto a:</0> length of the shadow of {1} in the direction of {2} (negative if it points in the opposite direction).",
"<0>Fläche des Parallelogramms</0>, das die beiden Vektoren aufspannen:": "<0>Area of the parallelogram</0> spanned by the two vectors:",
"{0}, Winkel {1}": "{0}, angle {1}",
"<0>Parameterform:</0> Vom Stützpunkt A aus geht man das t-Fache des Richtungsvektors.": "<0>Parametric form:</0> starting from the base point A, go t times the direction vector.",
"Punkt zum Parameter": "Point for the parameter",
"<0>Normalenvektor:</0> Die Komponenten des Richtungsvektors werden vertauscht, und eine wechselt das Vorzeichen. So wird das Skalarprodukt mit {1} null.": "<0>Normal vector:</0> the components of the direction vector are swapped, and one changes its sign. This makes the scalar product with {1} zero.",
"<0>Koordinatengleichung:</0> Für jeden Punkt der Geraden hat das Skalarprodukt mit {1} denselben Wert wie für A.": "<0>Coordinate equation:</0> for every point of the line the scalar product with {1} has the same value as for A.",
"Der Richtungsvektor hat keine x-Komponente: Die Gerade ist senkrecht und hat die Gleichung {0}.": "The direction vector has no x-component: the line is vertical and has the equation {0}.",
"<0>Funktionsgleichung:</0> Die Steigung ist das Verhältnis der Komponenten des Richtungsvektors.": "<0>Slope-intercept form:</0> the slope is the ratio of the components of the direction vector.",
"{0} liegt für {1} auf {2}": "{0} lies on {2} for {1}",
"Gerade:": "Line:",
"<0>Verbindungsvektor</0> vom Stützpunkt zum Punkt P:": "<0>Connecting vector</0> from the base point to the point P:",
"<0>Parameter des Lotfusspunkts:</0> {1} wird auf den Richtungsvektor projiziert.": "<0>Parameter of the foot of the perpendicular:</0> {1} is projected onto the direction vector.",
"<0>Lotfusspunkt:</0> {1} in die Geradengleichung einsetzen.": "<0>Foot of the perpendicular:</0> substitute {1} into the equation of the line.",
"<0>Abstand:</0> Länge des Vektors von P zum Lotfusspunkt.": "<0>Distance:</0> length of the vector from P to the foot of the perpendicular.",
"<0>Kontrolle:</0> Fläche des Parallelogramms aus {1} und {2}, geteilt durch die Grundseite {3}.": "<0>Check:</0> area of the parallelogram formed by {1} and {2}, divided by the base {3}.",
"<0>Spiegelpunkt:</0> Von P aus geht man zweimal den Weg zum Lotfusspunkt.": "<0>Mirror point:</0> from P, go twice the way to the foot of the perpendicular.",
