"Gebrochenrationale Funktionen": "Rational functions",
"{0}/x Gebrochenrationale Funktionen": "{0}/x Rational functions",
"Definitionslücken und Nullstellen": "Gaps in the domain and zeros",
"Asymptoten: Verhalten im Unendlichen": "Asymptotes: behaviour at infinity",
"Vorzeichen und Skizze": "Sign and sketch",
"Definitionslücken (Polstellen mit und ohne Vorzeichenwechsel, hebbare Lücken) und Nullstellen, waagrechte und schiefe Asymptoten, Polynomdivision Schritt für Schritt, Vorzeichen und Gebietseinteilung für die Skizze": "Gaps in the domain (poles with and without sign change, removable gaps) and zeros, horizontal and oblique asymptotes, polynomial division step by step, sign and regions for the sketch",
"Brüche aus zwei ganzrationalen Funktionen: Wo ist die Funktion nicht definiert, was geschieht an einer Polstelle, welcher Geraden nähert sich der Graph, und wie skizziert man ihn von Hand?": "Fractions of two polynomial functions: where is the function not defined, what happens at a pole, which line does the graph approach, and how do you sketch it by hand?",
"{0} Tippe links Zähler und Nenner als Terme in x ein und bestätige mit «Übernehmen» oder der Eingabetaste. Die Beispiele zeigen, was möglich ist.": "{0} Type the numerator and the denominator as terms in x on the left and confirm with “Apply” or the Enter key. The examples show what is possible.",
"Zähler und Nenner gibst du als Term in x ein: Zahlen, x, + und −, Klammern und Potenzen mit dem Zeichen ^. Das Malzeichen darf vor x und vor Klammern fehlen.": "Enter numerator and denominator as a term in x: numbers, x, + and −, brackets and powers with the ^ sign. The multiplication sign may be omitted before x and before brackets.",
"Der Zähler darf höchstens den Grad {0} haben, der Nenner höchstens den Grad {1}. Die Polynomdivision hat eigene Eingabefelder.": "The numerator may have degree {0} at most, the denominator degree {1} at most. Polynomial division has its own input fields.",
"Den violetten Punkt P ziehst du dem Graphen entlang; der Ausschnitt lässt sich mit der Maus verschieben und zoomen.": "Drag the violet point P along the graph; the view can be moved and zoomed with the mouse.",
"Eine gebrochenrationale Funktion ist ein Bruch aus zwei ganzrationalen Funktionen. Nullstellen des Nenners sind Definitionslücken. Ist dort auch der Zähler null und lässt sich der gemeinsame Faktor ganz kürzen, ist die Lücke hebbar; sonst liegt eine Polstelle vor.": "A rational function is a fraction of two polynomial functions. Zeros of the denominator are gaps in the domain. If the numerator is zero there as well and the common factor cancels completely, the gap is removable; otherwise there is a pole.",
"Zählergrad kleiner als Nennergrad: Die x-Achse ist Asymptote. Gleiche Grade: waagrechte Asymptote in der Höhe des Verhältnisses der höchsten Koeffizienten. Zählergrad um eins grösser: schiefe Asymptote; man findet sie mit der Polynomdivision.": "Degree of the numerator smaller than that of the denominator: the x-axis is the asymptote. Equal degrees: horizontal asymptote at the height of the ratio of the leading coefficients. Numerator degree greater by one: oblique asymptote; it is found by polynomial division.",
"Jede gebrochenrationale Funktion, deren Zählergrad mindestens so gross ist wie der Nennergrad, lässt sich in eine ganzrationale Funktion und einen Restbruch zerlegen. Geht die Division ohne Rest auf, ist der Nenner ein Faktor des Zählers.": "Every rational function whose numerator degree is at least as large as the denominator degree can be split into a polynomial function and a remainder fraction. If the division leaves no remainder, the denominator is a factor of the numerator.",
"Gebietseinteilung: An einfachen Nullstellen und an Polstellen ungerader Ordnung wechselt das Vorzeichen, an doppelten Nullstellen und an Polstellen gerader Ordnung nicht. Ein Probewert pro Abschnitt genügt.": "Dividing the plane into regions: at simple zeros and at poles of odd order the sign changes, at double zeros and at poles of even order it does not. One test value per section is enough.",
"Dieser Term wird nicht verstanden. Erlaubt sind x, Zahlen, Plus, Minus, Mal, Klammern und Potenzen; der Zähler höchstens vom Grad vier, der Nenner höchstens vom Grad drei und nicht null.": "This term is not understood. Allowed are x, numbers, plus, minus, times, brackets and powers; the numerator of degree four at most, the denominator of degree three at most and not zero.",
"Polstelle (rot)": "pole (red)",
"hebbaren Lücke": "removable gap",
"Nullstellen der Funktion": "zeros of the function",
"violetten Punkt auf dem Graphen": "violet point on the graph",
"Wo der Nenner null wird, ist die Funktion nicht definiert: An einer {0} verschwindet der Graph nach oben oder unten, an einer {1} fehlt nur ein einzelner Punkt. Die {2} liegen dort, wo nur der Zähler null wird. Ziehe den {3} nahe an eine Lücke.": "Where the denominator is zero, the function is not defined: at a {0} the graph disappears upwards or downwards, at a {1} only a single point is missing. The {2} are where only the numerator is zero. Drag the {3} close to a gap.",
"blaue Graph": "blue graph",
"orange Asymptote": "orange asymptote",
"Punkt P nach aussen": "point P outwards",
"Abstand zur Asymptote": "distance to the asymptote",
"Für sehr grosse und sehr kleine x schmiegt sich der {0} an die {1}. Ziehe den {2}: Der {3} wird beliebig klein. Welche Asymptote entsteht, entscheiden die Grade von Zähler und Nenner.": "For very large and very small x the {0} hugs the {1}. Drag the {2}: the {3} becomes arbitrarily small. Which asymptote arises is decided by the degrees of numerator and denominator.",
"Quotienten (grün)": "quotient (green)",
"zurückmultiplizieren": "multiply back",
"abziehen": "subtract",
"Die Polynomdivision läuft wie die schriftliche Division von Zahlen: höchste Potenzen teilen und das Ergebnis zum {0} schreiben, {1}, {2} und von vorn beginnen, bis der Rest einen kleineren Grad hat als der Nenner. Stelle links ein, wie viele Schritte gezeigt werden.": "Polynomial division works like long division of numbers: divide the highest powers and write the result into the {0}, {1}, {2} and start again, until the remainder has a smaller degree than the denominator. Set on the left how many steps are shown.",
"Nullstellen und Polstellen": "zeros and poles",
"grauen Feldern": "grey regions",
"Polgeraden": "pole lines",
"Verlauf des Graphen": "course of the graph",
"Zwischen {0} kann die Funktion ihr Vorzeichen nicht wechseln. Der Streifen unten zeigt das Vorzeichen für jeden Abschnitt; in den {1} verläuft kein Graph. Zusammen mit {2} und Asymptote lässt sich der {3} so von Hand skizzieren.": "Between {0} the function cannot change its sign. The strip at the bottom shows the sign for each section; no graph runs in the {1}. Together with the {2} and the asymptote, the {3} can be sketched by hand.",
