"Doppelte Nullstelle: kein Vorzeichenwechsel": "Double zero: no sign change",
"Doppelte Polstelle: kein Vorzeichenwechsel": "Double pole: no sign change",
"Überall positiv": "Positive everywhere",
"Die x-Achse ist waagrechte Asymptote.": "The x-axis is the horizontal asymptote.",
"Waagrechte Asymptote {0}": "Horizontal asymptote {0}",
"Schiefe Asymptote {0}": "Oblique asymptote {0}",
