"Ganzrationale Funktion: keine Asymptote": "Polynomial function: no asymptote",
"Der Zähler hat einen kleineren Grad als der Nenner: Es gibt nichts zu teilen.": "The numerator has a smaller degree than the denominator: there is nothing to divide.",
"<0>Nenner null setzen:</0> Dort ist die Funktion nicht definiert.": "<0>Set the denominator to zero:</0> there the function is not defined.",
"Der Nenner wird für keine reelle Zahl null: Die Funktion ist überall definiert.": "The denominator is not zero for any real number: the function is defined everywhere.",
"Der Nenner ist eine Zahl: Das ist eine ganzrationale Funktion ohne Definitionslücken.": "The denominator is a number: this is a polynomial function without gaps in the domain.",
"<0>Stelle</0> {1}: Der Zähler ist dort nicht null.": "<0>At</0> {1}: the numerator is not zero there.",
"<0>Stelle</0> {1}: Auch der Zähler ist dort null. Der gemeinsame Faktor {2} lässt sich kürzen.": "<0>At</0> {1}: the numerator is zero there as well. The common factor {2} can be cancelled.",
"<0>Stelle</0> {1}: Zähler und Nenner sind beide null, aber der Nenner öfter. Nach dem Kürzen bleibt der Faktor im Nenner stehen.": "<0>At</0> {1}: numerator and denominator are both zero, but the denominator more often. After cancelling, the factor remains in the denominator.",
"Polstelle mit Vorzeichenwechsel: Der Graph verschwindet auf der einen Seite nach oben, auf der anderen nach unten.": "Pole with sign change: the graph disappears upwards on one side and downwards on the other.",
"Polstelle ohne Vorzeichenwechsel: Der Nenner hat hier eine doppelte Nullstelle, der Graph verschwindet auf beiden Seiten in dieselbe Richtung.": "Pole without sign change: the denominator has a double zero here, the graph disappears in the same direction on both sides.",
"Polstelle mit Vorzeichenwechsel.": "Pole with sign change.",
"Polstelle ohne Vorzeichenwechsel.": "Pole without sign change.",
"Hebbare Lücke: Im Graphen fehlt nur der Punkt {0}.": "Removable gap: only the point {0} is missing from the graph.",
"<0>Gekürzter Term:</0> Er stimmt ausserhalb der Lücken mit {1} überein.": "<0>Reduced term:</0> outside the gaps it agrees with {1}.",
"<0>Nullstellen:</0> Der Zähler ist null, der Nenner nicht.": "<0>Zeros:</0> the numerator is zero, the denominator is not.",
"Es gibt keine Nullstellen.": "There are no zeros.",
"Der Zähler ist überall null: Die Funktion hat ausserhalb der Lücken überall den Wert {0}.": "The numerator is zero everywhere: outside the gaps the function has the value {0} everywhere.",
"Polstellen: {0}, hebbare Lücken: {1}, Nullstellen: {2}": "Poles: {0}, removable gaps: {1}, zeros: {2}",
"Keine Definitionslücken, Nullstellen: {0}": "No gaps in the domain, zeros: {0}",
"<0>Grade vergleichen:</0> Der Zähler hat den Grad {1}, der Nenner den Grad {2}.": "<0>Compare the degrees:</0> the numerator has degree {1}, the denominator degree {2}.",
"Der Nenner ist eine Zahl: Das ist eine ganzrationale Funktion. Sie hat keine Asymptote.": "The denominator is a number: this is a polynomial function. It has no asymptote.",
"<0>Zählergrad kleiner:</0> Für grosse {1} wächst der Nenner schneller als der Zähler, der Bruch geht gegen {2}.": "<0>Numerator degree smaller:</0> for large {1} the denominator grows faster than the numerator, the fraction tends to {2}.",
"<0>Gleicher Grad:</0> Für grosse {1} zählen nur die höchsten Potenzen; ihr Verhältnis ist der Grenzwert.": "<0>Equal degree:</0> for large {1} only the highest powers count; their ratio is the limit.",
"<0>Zählergrad um eins grösser:</0> Die Polynomdivision spaltet eine Gerade ab, die schiefe Asymptote.": "<0>Numerator degree greater by one:</0> polynomial division splits off a straight line, the oblique asymptote.",
"<0>Zählergrad um mehr als eins grösser:</0> Die Polynomdivision spaltet eine ganzrationale Funktion ab; an ihren Graphen schmiegt sich die Kurve.": "<0>Numerator degree greater by more than one:</0> polynomial division splits off a polynomial function; the curve hugs its graph.",
"<0>Zerlegung:</0> ganzrationaler Teil plus Restbruch. Der Restbruch geht für grosse {1} gegen {2}.": "<0>Decomposition:</0> polynomial part plus remainder fraction. The remainder fraction tends to {2} for large {1}.",
"Die Division geht ohne Rest auf: Ausserhalb der Lücken ist der Graph genau diese Gerade.": "The division leaves no remainder: outside the gaps the graph is exactly this line.",
"Die Division geht ohne Rest auf: Ausserhalb der Lücken ist der Graph genau diese Kurve.": "The division leaves no remainder: outside the gaps the graph is exactly this curve.",
"<0>Abstand zur Asymptote</0> an der Stelle {1}: Funktionswert minus Wert der Asymptote.": "<0>Distance to the asymptote</0> at {1}: function value minus value of the asymptote.",
"<0>Schritt {1}:</0> höchste Potenzen teilen, zurückmultiplizieren, abziehen.": "<0>Step {1}:</0> divide the highest powers, multiply back, subtract.",
"<0>Ende:</0> Der Rest hat einen kleineren Grad als der Nenner. Er bleibt als Bruch stehen.": "<0>End:</0> the remainder has a smaller degree than the denominator. It stays as a fraction.",
"<0>Ende:</0> Der Rest ist {1}, die Division geht auf.": "<0>End:</0> the remainder is {1}, the division works out exactly.",
"<0>Probe:</0> Quotient mal Nenner plus Rest ergibt den Zähler.": "<0>Check:</0> quotient times denominator plus remainder gives the numerator.",
"Quotient {0}, Rest {1}": "Quotient {0}, remainder {1}",
"Der Zähler hat einen kleineren Grad als der Nenner: Es gibt nichts zu teilen, der Bruch ist schon der Rest.": "The numerator has a smaller degree than the denominator: there is nothing to divide, the fraction is already the remainder.",
"{0} bleibt, wie es ist": "{0} stays as it is",
"<0>Stellen, an denen das Vorzeichen wechseln kann:</0> Nullstellen des Zählers und des Nenners.": "<0>Places where the sign can change:</0> zeros of the numerator and of the denominator.",
"Es gibt weder Nullstellen noch Definitionslücken: Die Funktion hat überall dasselbe Vorzeichen.": "There are neither zeros nor gaps in the domain: the function has the same sign everywhere.",
"Bei {0} liegt eine doppelte Nullstelle: Der Graph berührt die x-Achse, das Vorzeichen bleibt.": "At {0} there is a double zero: the graph touches the x-axis, the sign stays.",
"Bei {0} liegt eine Polstelle ohne Vorzeichenwechsel.": "At {0} there is a pole without sign change.",
"<0>Probewerte:</0> In jedem Abschnitt genügt ein einziger Wert, denn dazwischen kann das Vorzeichen nicht wechseln.": "<0>Test values:</0> a single value is enough in each section, because the sign cannot change in between.",
"<0>Für grosse</0> {1} nähert sich der Graph der Asymptote.": "<0>For large</0> {1} the graph approaches the asymptote.",
