"Rechenweg: Ebenen entdecken": "Working: Discovering planes",
"Drehe den Raum mit der Maus: Über jedem {0} steht ein {1}, dessen {2} aus der Gleichung folgt (Beispiele rechts). Schalte danach links «Nur Punkte (ohne Balken)» ein.": "Rotate the space with the mouse: above each {0} stands a {1} whose {2} follows from the equation (examples on the right). Then switch on «Points only (no bars)» on the left.",
