"Je kleiner der Gitterabstand, desto dichter liegen die Punkte. Alle Punkte, deren Koordinaten die Gleichung erfüllen, bilden zusammen die <0>Ebene</0>.": "The smaller the grid spacing, the closer together the points lie. All points whose coordinates satisfy the equation together form the <0>plane</0>.",
